(()=>{'use strict';
const C=window.OGE_CONFIG,P=window.OGE_PROGRAM,D=window.OGE_DIAGNOSTIC;
const L=window.OGE_LESSONS, R=window.OGE_REPORTS_CORE;
if(!C||!P||!D||!L){document.getElementById('app').textContent='Не удалось загрузить данные сайта.';return;}
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 10h18"/>',book:'<path d="M12 7a7 7 0 0 0-9-2v15a7 7 0 0 1 9 2 7 7 0 0 1 9-2V5a7 7 0 0 0-9 2zM12 7v15"/>',layers:'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M7 8h10M7 12h10M7 16h6"/>',chart:'<path d="M4 20V11M10 20V4M16 20v-9M22 20v-6"/>',headphones:'<path d="M3 14v-3a9 9 0 0 1 18 0v3M3 14v4a2 2 0 0 0 2 2h2v-8H5a2 2 0 0 0-2 2Zm18 0v4a2 2 0 0 1-2 2h-2v-8h2a2 2 0 0 1 2 2Z"/>',edit:'<path d="M12 20h9M4 20l4-.8L20 7a2 2 0 0 0-3-3L5 16l-1 4Z"/>',mic:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10a7 7 0 0 0 14 0M12 17v5M8 22h8"/>',check:'<path d="m5 12 4 4L19 6"/>',checkCircle:'<circle cx="12" cy="12" r="9"/><path d="m7.5 12 3 3 6-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',arrow:'<path d="M5 12h14m-7-7 7 7-7 7"/>',left:'<path d="m15 18-6-6 6-6"/>',right:'<path d="m9 18 6-6-6-6"/>',sparkles:'<path d="m12 3 2.1 6.9L21 12l-6.9 2.1L12 21l-2.1-6.9L3 12l6.9-2.1L12 3ZM19 3v3M17.5 4.5h3"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M19 5l-2 2M7 17l-2 2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v3h16v-3"/>',upload:'<path d="M12 18V6m-5 5 5-5 5 5M4 7V4h16v3"/>',trash:'<path d="M4 7h16M9 7V4h6v3m3 0-1 14H7L6 7"/>',volume:'<path d="M4 9h4l5-5v16l-5-5H4zM17 9a4 4 0 0 1 0 6M19 6a8 8 0 0 1 0 12"/>',flag:'<path d="M5 21V3m0 1c5-3 9 3 15 0v11c-6 3-10-3-15 0"/>',lock:'<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',mail:'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="m3 7 9 7 9-7"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 7h.01"/>',refresh:'<path d="M20 11a8 8 0 1 0-2 6m2-12v6h-6"/>',chevron:'<path d="m6 9 6 6 6-6"/>',pen:'<path d="m12 19 9-9-6-6-9 9-2 8zM13 6l6 6"/>',play:'<path d="m8 5 11 7-11 7z"/>',pause:'<path d="M7 5v14m10-14v14"/>'};
const svg=(name,more='')=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" ${more}>${icons[name]||icons.info}</svg>`;
const defaults=()=>({version:1,studentId:C.student.id,startedAt:null,diagnostic:{answers:{},finishedAt:null,result:null},weeks:{},grammar:{},vocab:{},verbs:{},practice:{},writing:{text:'',checks:{}},sessions:{},sessionDrafts:{},weekStudyDays:{},events:[]});
let persistenceError='';
let state=load(),filters={vocabTopic:'v1',vocabSearch:'',vocabStatus:'all',verbSearch:'',grammarSearch:'',verbStage:'v2',flashIndex:0,flashShow:false,diagnosticIndex:0,reviewOpen:false,mode:'all'};
let lessonAnswers={}, lessonFeedback=null, mistakeAnswers={}, mistakeFeedback=null;
let rec=null,recStream=null,recChunks=[],recUrl=null,recMime='',recording=false,verbQuizAnswer='';
// Прогресс находится в хранилище текущего адреса сайта. При file:// и без
// Supabase он НЕ переносится на другое устройство или в другой браузер.
function load(){
  try{
    const raw=localStorage.getItem(C.storageKey);
    if(!raw)return defaults();
    const data=JSON.parse(raw);
    if(!data||data.studentId!==C.student.id||data.version!==1){
      persistenceError='Найдены данные несовместимой версии. Не сбрасывай данные и сохрани резервную копию.';
      return defaults();
    }
    return {...defaults(),...data,diagnostic:{...defaults().diagnostic,...data.diagnostic},writing:{...defaults().writing,...data.writing},sessions:data.sessions||{},sessionDrafts:data.sessionDrafts||{},weekStudyDays:data.weekStudyDays||{},events:data.events||[]};
  }catch(e){
    persistenceError='Не удалось прочитать сохранение: '+(e?.message||'ошибка браузера');
    return defaults();
  }
}
function save(){
  try{
    if(persistenceError&&persistenceError.startsWith('Найдены данные несовместимой'))throw Error('Не заменяем несовместимые данные');
    const snapshot=JSON.stringify(state);
    localStorage.setItem(C.storageKey,snapshot);
    if(localStorage.getItem(C.storageKey)!==snapshot)throw Error('Браузер не подтвердил запись');
    persistenceError='';
    window.dispatchEvent(new Event('oge-progress-saved'));
    return true;
  }catch(e){
    persistenceError=e?.message||'Не удалось записать данные';
    notify('Прогресс НЕ сохранён. Скачай резервную копию на странице настроек.');
    return false;
  }
}
function persistenceNotice(){
  const cloud=window.OGE_CLOUD?.status?.();
  if(cloud?.connected&&cloud.syncedAt&&!cloud.error)return '';
  const isFile=location.protocol==='file:';
  const label=persistenceError?'Ошибка сохранения':isFile?'Сайт открыт как файл':'Нет облачного сохранения';
  const message=persistenceError?`Сохранение в браузере не подтверждено: ${esc(persistenceError)}. Скачай резервную копию сейчас.`:isFile?'При открытии ZIP как файла результаты могут быть недоступны после смены папки, браузера или устройства. Для постоянной подготовки нужен HTTPS-сайт с подключённым аккаунтом Supabase.':'Результаты сохраняются только в этом браузере на этом адресе. При смене устройства или очистке данных они не появятся автоматически.';
  return `<div class="notice warning save-warning" role="status"><div><strong>${label}</strong><p class="small" style="margin:6px 0 0">${message}</p></div><button class="btn btn-outline btn-sm" data-act="export-data">Скачать копию прогресса</button></div>`;
}
function track(type,data={}) { const event={id:'kr-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,11),type,date:new Date().toISOString(),...data};state.events.push(event);return event }
/* Обмен прогрессом между браузером и облаком. Сохраняем объединение попыток,
   отметок, дней и событий, не отбрасывая данные другого устройства. */
function mergeProgress(local,remote){
  if(!remote || remote.studentId!==C.student.id || remote.version!==1)return local;
  const a=local,b=remote,out={...a};
  const mergeFlags=(x={},y={})=>{const v={...y,...x};for(const k of Object.keys(y))if(y[k]===true||y[k]==='known'||(y[k]?.done===true)){
    if(typeof y[k]==='object')v[k]={...y[k],...(typeof x[k]==='object'?x[k]:{}),done:!!(y[k].done||x[k]?.done),best:Math.max(y[k].best||0,x[k]?.best||0)};
    else v[k]=y[k];
  }return v};
  out.vocab=mergeFlags(a.vocab,b.vocab);
  out.verbs=mergeFlags(a.verbs,b.verbs);
  out.grammar=mergeFlags(a.grammar,b.grammar);
  out.practice=mergeFlags(a.practice,b.practice);
  out.weeks=mergeFlags(a.weeks,b.weeks);
  out.sessions={...b.sessions,...a.sessions};
  for(const id of new Set([...Object.keys(a.sessions||{}),...Object.keys(b.sessions||{})])){
    const x=a.sessions?.[id]||{},y=b.sessions?.[id]||{};
    const newer=(x.lastAttemptAt||'')>(y.lastAttemptAt||'')?x:y;
    out.sessions[id]={...x,...y,...newer,passed:!!(x.passed||y.passed),best:Math.max(x.best||0,y.best||0),attempts:Math.max(x.attempts||0,y.attempts||0),firstPassedAt:[x.firstPassedAt,y.firstPassedAt].filter(Boolean).sort()[0]||null};
  }
  out.weekStudyDays={...b.weekStudyDays,...a.weekStudyDays};
  for(const k of Object.keys(b.weekStudyDays||{}))out.weekStudyDays[k]=[...new Set([...(a.weekStudyDays?.[k]||[]),...(b.weekStudyDays[k]||[])])].sort();
  out.sessionDrafts={...b.sessionDrafts,...a.sessionDrafts};
  for(const k of Object.keys(b.sessionDrafts||{}))if((b.sessionDrafts[k]||'').length>(a.sessionDrafts?.[k]||'').length)out.sessionDrafts[k]=b.sessionDrafts[k];
  out.diagnostic=(a.diagnostic?.finishedAt||'')>=(b.diagnostic?.finishedAt||'')?a.diagnostic:b.diagnostic;
  if(!a.diagnostic?.finishedAt&&!b.diagnostic?.finishedAt)out.diagnostic={...b.diagnostic,...a.diagnostic,answers:{...b.diagnostic?.answers,...a.diagnostic?.answers}};
  out.writing=(a.writing?.text||'').length>=(b.writing?.text||'').length?a.writing:b.writing;
  const events=[...(b.events||[]),...(a.events||[])],byId=new Map();
  events.forEach((e,i)=>{if(e?.date&&e?.type)byId.set(e.id||'legacy-'+e.type+'-'+e.date+'-'+i,e)});
  out.events=[...byId.values()].sort((x,y)=>x.date.localeCompare(y.date));
  out.startedAt=[a.startedAt,b.startedAt].filter(Boolean).sort()[0]||null;
  return out;
}
window.OGE_STATE_BRIDGE={read:()=>structuredClone(state),merge:mergeProgress,apply:next=>{
  if(!next||next.studentId!==C.student.id||next.version!==1)return;
  state=next;try{localStorage.setItem(C.storageKey,JSON.stringify(state))}catch(e){notify('Не удалось сохранить облачную копию на устройстве')}
  render();
}};
function questionLog(q,chosen,domain,topic){return {id:q.id||'',domain,topic:topic||'Общая практика',correct:chosen===q.answer}}
function reportPreview(kind){if(!R)return null;return kind==='month'?R.monthlyReport(state.events):R.weeklyReport(state.events)}
function notify(t){const el=document.createElement('div');el.className='toast';el.setAttribute('role','status');el.textContent=t;document.body.appendChild(el);setTimeout(()=>el.remove(),3100)}
function dateLocal(s){let [y,m,d]=s.split('-').map(Number);return new Date(y,m-1,d)}
function localStartToday(){
 const parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Yekaterinburg',year:'numeric',month:'numeric',day:'numeric'}).formatToParts(new Date());
 const part=k=>Number(parts.find(p=>p.type===k)?.value);
 return new Date(part('year'),part('month')-1,part('day'));
}
function dayDiff(a,b){return Math.round((Date.UTC(b.getFullYear(),b.getMonth(),b.getDate())-Date.UTC(a.getFullYear(),a.getMonth(),a.getDate()))/86400000)}
function remaining(){return Math.max(0,dayDiff(localStartToday(),dateLocal(C.goalDate)))}
function weekNow(){return Math.max(0,Math.min(28,Math.floor(dayDiff(dateLocal(C.programStart),localStartToday())/7)))}
function dayStr(date){return new Intl.DateTimeFormat('ru-RU',{day:'numeric',month:'long'}).format(date)}
function rangeWeek(i){let d=dateLocal(C.programStart);d.setDate(d.getDate()+7*i);let e=new Date(d);e.setDate(e.getDate()+6);if(e>dateLocal(C.goalDate))e=dateLocal(C.goalDate);return `${dayStr(d)} – ${dayStr(e)}`}
function learnedWords(){return Object.values(state.vocab).filter(s=>s==='known').length}
function learnedVerbs(){return Object.values(state.verbs).filter(Boolean).length}
function learnedGrammar(){return Object.values(state.grammar).filter(x=>x?.done).length}
function grammarTotal(){return P.grammarGroups.reduce((n,g)=>n+g.topics.length,0)}
function percent(n,t){return t?Math.round(100*n/t):0}
function pbar(n,total,extra=''){return `<div class="progress-track"><div class="progress-fill ${extra}" style="width:${percent(n,total)}%"></div></div>`}
function param(name){let h=location.hash.split('?')[1]||'';return new URLSearchParams(h).get(name)}
function route(){let h=location.hash.split('?')[0];try{h=decodeURIComponent(h)}catch(e){}return (h.replace(/^#\/?/,'')||'главная').toLowerCase()}
function navlink(url){const next='#/'+url;try{if(decodeURIComponent(location.hash)===next){render();window.scrollTo(0,0);return}}catch(e){}location.hash=next;render();window.scrollTo(0,0)}
function navItems(){return [['главная','Главная','home'],['занятия','Мои занятия','calendar'],['план','План подготовки','chart'],['повторение','Повторение','refresh'],['диагностика','Стартовый тест','target'],['грамматика','Грамматика','layers'],['словарь','Словарь','book'],['тренажёр','Тренажёр ОГЭ','headphones'],['отчёты','Отчёты','chart'],['материалы','Материалы','download'],['настройки','Настройки','settings']]}
function navActive(r,item){if(r===item)return true;if(r==='неделя'&&item==='план')return true;if(r==='урок'&&item==='занятия')return true;if(r==='ошибки'&&item==='повторение')return true;if(r==='правило'&&item==='грамматика')return true;if(['глаголы','карточки'].includes(r)&&item==='словарь')return true;if(['задания','письмо','говорение'].includes(r)&&item==='тренажёр')return true;return false}
function sidebar(r){return `<aside class="sidebar"><a class="brand" href="#/главная"><div class="brand-logo"><img src="assets/logo.svg" alt=""></div><div><strong>Мой ОГЭ<span style="color:var(--indigo)">.</span></strong><small>АНГЛИЙСКИЙ · 2027</small></div></a><div><div class="menu-label">Моё обучение</div><nav class="nav-stack" aria-label="Основная навигация">${navItems().slice(0,8).map(([path,title,ic])=>`<a class="nav-item ${navActive(r,path)?'active':''}" href="#/${path}">${svg(ic)} ${title}</a>`).join('')}</nav></div><div><div class="menu-label">Дополнительно</div><nav class="nav-stack">${navItems().slice(8).map(([path,title,ic])=>`<a class="nav-item ${navActive(r,path)?'active':''}" href="#/${path}">${svg(ic)} ${title}</a>`).join('')}</nav></div><div class="sidebar-bottom"><div class="sidebar-goal"><small>ТВОЯ ЦЕЛЬ</small><strong>1 мая 2027</strong><p>Завершить подготовку и уверенно подойти к экзамену</p></div><div class="user-chip"><div class="avatar">К</div><div><strong>${esc(C.student.name)}</strong><small>Личный кабинет</small></div></div></div></aside>`}
function chrome(r,content){let mobile=navItems().filter(x=>['главная','занятия','план','повторение','диагностика'].includes(x[0]));return `<div class="shell">${sidebar(r)}<main class="main"><div class="mobile-top"><div class="mobile-brand"><img src="assets/logo.svg" alt=""> Мой ОГЭ · 2027</div><span class="pill">${remaining()} дн. до цели</span></div><div class="topbar"><span class="crumb">МОЙ ОГЭ / ${esc(navItems().find(x=>navActive(r,x[0]))?.[1]||'Подготовка')}</span><div class="top-actions"><span class="date-pill">${dayStr(localStartToday())}</span><a class="circle-button" href="#/настройки" aria-label="Настройки">${svg('settings')}</a></div></div><div class="content">${persistenceNotice()}${window.OGE_CLOUD?.status?.().enabled&&!window.OGE_CLOUD?.status?.().connected?'<div class="notice warning" style="margin-bottom:16px"><strong>Подключи сохранение в облаке</strong><p class="small">Пока ты не войдёшь в аккаунт, выполненный тест виден только на этом устройстве. <a href="#/настройки">Войти и перенести результаты →</a></p></div>':''}${content}<div class="footer-note">Учебная платформа Кристины · материалы и тренировочные задания не заменяют официальные документы ФИПИ.</div></div></main><nav class="mobile-nav" aria-label="Мобильная навигация">${mobile.map(([path,title,ic])=>`<a href="#/${path}" class="${navActive(r,path)?'active':''}">${svg(ic)}<span>${title.replace(' подготовки','').replace('Стартовый ','')}</span></a>`).join('')}</nav></div>`}
function heading(label,title,desc='',right=''){return `<div class="page-heading"><div><span class="eyebrow">${label}</span><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${right}</div>`}
function stat(label,val,icon,color='',detail=''){return `<div class="card stat"><div><small>${label}</small><strong>${val}</strong>${detail?`<div class="text-muted small" style="margin-top:7px">${detail}</div>`:''}</div><div class="stat-icon ${color}">${svg(icon)}</div></div>`}
function quote(){const seed=Math.floor(Date.UTC(localStartToday().getFullYear(),localStartToday().getMonth(),localStartToday().getDate())/86400000);return P.quotes[seed%P.quotes.length]}
function dashboard(){const w=P.weeks[weekNow()],doneWeeks=P.weeks.filter(w=>weekComplete(w.id)).length,diagnosed=!!state.diagnostic.finishedAt;return `<section class="hero"><div class="hero-copy"><span class="eyebrow">ЛИЧНЫЙ МАРШРУТ · АНГЛИЙСКИЙ</span><h1>Привет, Кристина!<br>У тебя всё получится.</h1><p>Твоя подготовка без хаоса: понятные шаги, повторение и движение к цели в своём темпе.</p><a class="btn btn-light" href="#/${diagnosed?'занятия':'диагностика'}">${diagnosed?'Продолжить подготовку':'Начать с диагностики'} ${svg('arrow')}</a></div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 220 205"><ellipse cx="120" cy="181" rx="78" ry="12" fill="#4a3aa9" opacity=".25"/><g transform="rotate(-10 101 106)"><rect x="48" y="41" width="127" height="135" rx="17" fill="#dcd6ff"/><rect x="57" y="35" width="127" height="135" rx="15" fill="#fff"/><rect x="80" y="58" width="68" height="11" rx="5" fill="#7469db"/><rect x="80" y="81" width="75" height="5" rx="2" fill="#dedaf7"/><rect x="80" y="95" width="82" height="5" rx="2" fill="#dedaf7"/><rect x="80" y="109" width="68" height="5" rx="2" fill="#dedaf7"/><rect x="80" y="125" width="66" height="24" rx="9" fill="#eaf7ef"/><path d="m99 138 6 5 10-11" fill="none" stroke="#54b293" stroke-width="4" stroke-linecap="round"/></g><circle cx="32" cy="59" r="12" fill="#f8cb96"/><path d="m32 50 2 7 7 2-7 2-2 7-2-7-7-2 7-2z" fill="#fff"/><circle cx="183" cy="39" r="8" fill="#f2c6da"/></svg></div></section><div class="grid g-4" style="margin:19px 0 25px">${stat('До дедлайна',remaining()+' дн.','calendar','','1 мая 2027')}${stat('Пройдено недель',`${doneWeeks}/29`,'checkCircle','green')}${stat('Слов выучено',learnedWords(),'book','orange',`из ${P.vocabulary.reduce((n,x)=>n+x.words.length,0)} в стартовой базе`)}${stat('Грамматика',`${learnedGrammar()}/${grammarTotal()}`,'layers','pink')}</div><div class="grid g-2" style="align-items:start"><section class="card"><div class="section-head"><h2>Твоя подготовка</h2><a class="text-link" href="#/занятия">Мои занятия ${svg('arrow','class="inline-icon"')}</a></div><div class="progress-meta"><span>Пройденные недели</span><strong>${percent(doneWeeks,29)}%</strong></div>${pbar(doneWeeks,29)}<div style="height:21px"></div><span class="pill">Неделя ${weekNow()+1} из 29</span><h3 style="margin:11px 0 5px">${esc(w.title)}</h3><p style="font-size:12px;margin-bottom:15px">${esc(w.grammar)} · ${esc(w.vocab)}</p><div class="timeline-mini">${[['Грамматика',w.grammar],['Словарь',w.vocab],['Формат ОГЭ',w.skill]].map((x,i)=>`<div class="timeline-item"><div class="timeline-dot">${i+1}</div><div><strong>${esc(x[0])}</strong><p>${esc(x[1])}</p></div></div>`).join('')}</div><div style="margin-top:20px"><a class="btn btn-primary" href="#/занятия">Начать занятия ${svg('arrow')}</a></div></section><div class="grid" style="gap:18px;align-content:start"><section class="card"><div class="section-head"><h2>С чего начать</h2><span class="pill ${diagnosed?'green':'orange'}">${diagnosed?'Пройдено':'Важно'}</span></div><a class="lesson-link" href="#/диагностика"><div><strong>${diagnosed?'Результаты стартового теста':'Узнай свой начальный уровень'}</strong><p>${diagnosed?'Посмотри сильные стороны и темы для повторения':'44 вопроса по грамматике, лексике и чтению. Результат поможет выбрать маршрут.'}</p></div>${svg('arrow','width="18" height="18"')}</a><a class="lesson-link" style="margin-top:10px" href="#/глаголы"><div><strong>Неправильные глаголы</strong><p>${learnedVerbs()} из ${P.verbs.length} отмечено как изученные</p></div>${svg('arrow','width="18" height="18"')}</a></section><section class="quote-card"><div class="quote-mark">“</div><h3 style="color:#9b6f50;margin:2px 0 10px">Мысль дня</h3><p>${esc(quote())}</p></section><section class="card"><div class="section-head"><h2>Разделы ОГЭ</h2><a class="text-link" href="#/тренажёр">Тренироваться</a></div>${P.examSections.map(x=>`<div class="compact-stat"><span style="font-size:12px;font-weight:700">${svg(x.icon,'class="inline-icon"')} ${x.name}</span><span class="pill gray">${x.numbers}</span></div>`).join('')}</section></div></div>`}
function plan(){let current=weekNow(),n=P.weeks.filter(w=>weekComplete(w.id)).length;return `${heading('Маршрут до дедлайна','План на 29 недель','На каждой неделе три самостоятельных занятия в разные дни. Прохождение определяется результатами упражнений, а не ручной отметкой.',`<span class="pill">${n}/29 недель завершено</span>`)}<div class="card" style="margin-bottom:19px"><div class="section-head"><h2>Недельная нагрузка</h2><span class="pill">Цель · 1 мая 2027</span></div><p>Три занятия в неделю по 45–65 минут плюс свободное повторение. Удобный ориентир — понедельник, среда и суббота, но можно выбрать любые три дня.</p><div class="plan-stats">${L.sessions.map(s=>`<div class="mini-tile"><strong>${esc(s.name)}</strong><small>${esc(s.minutes)} мин</small></div>`).join('')}</div><div class="progress-meta"><span>Недели, завершённые в разные дни</span><strong>${percent(n,29)}%</strong></div>${pbar(n,29)}<div style="margin-top:18px"><a href="#/занятия" class="btn btn-primary">Открыть мои занятия ${svg('arrow')}</a></div></div><div class="week-grid">${P.weeks.map((w,i)=>`<button class="week-card ${i===current?'current':''} ${weekComplete(w.id)?'done':''}" data-act="go-week" data-id="${w.id}"><div class="row justify-between"><small>НЕДЕЛЯ ${String(i+1).padStart(2,'0')}</small><span class="pill ${weekComplete(w.id)?'green':i===current?'':'gray'}">${weekComplete(w.id)?'Завершена':weekSessionsDone(w.id)+'/3 занятия'}</span></div><h3>${esc(w.title)}</h3><p>${esc(w.grammar)}</p><small>${rangeWeek(i)}</small></button>`).join('')}</div>`}
function weekPage(){let w=P.weeks.find(x=>x.id===param('id'))||P.weeks[weekNow()],i=P.weeks.indexOf(w);return `<a class="back-link" href="#/план">${svg('left','class="inline-icon"')} Все недели</a>${heading('НЕДЕЛЯ '+(i+1)+' · '+rangeWeek(i),esc(w.title),'Три занятия на отдельных днях плюс возможность повторить любой материал.')}${weekOverview(w,i)}<div class="card" style="margin-top:18px"><h2>Что ещё повторить</h2><p style="margin-top:12px">В разделе «Повторение» можно заниматься сверх обязательной программы.</p><a class="btn btn-outline" href="#/повторение">Открыть повторение ${svg('arrow')}</a></div>`}
function diagnosticIntro(){const fin=!!state.diagnostic.finishedAt,n=Object.keys(state.diagnostic.answers).length;return `${heading('Начало подготовки','Стартовая диагностика','Поможет увидеть сильные и слабые стороны до составления окончательного учебного маршрута.')}<div class="grid g-2"><div class="card"><span class="pill">44 задания · приблизительно 35–50 минут</span><h2 style="margin:17px 0 12px">Узнай свою отправную точку</h2><p style="font-size:13px;line-height:1.85">Авторские вопросы от A1 до B1 по грамматике, лексике и чтению. Варианты ответов перемешаны. Можно прервать тест: ответы сохраняются в текущем браузере, если он разрешает хранение данных. После теста скачай резервную копию.</p><div class="checklist" style="margin:20px 0"><div class="checkline">${svg('checkCircle','class="inline-icon"')} Вопросы по основным грамматическим конструкциям</div><div class="checkline">${svg('checkCircle','class="inline-icon"')} Словарный запас в контексте</div><div class="checkline">${svg('checkCircle','class="inline-icon"')} Два текста с проверкой понимания</div></div><div class="notice warning">Это ориентировочная диагностика отдельных навыков, а не сертифицированное определение уровня CEFR. Аудирование, письмо и говорение проверяются отдельно.</div><div class="quick-actions" style="margin-top:20px"><button class="btn btn-primary" data-act="start-test">${fin?'Пройти ещё раз':n?'Продолжить тест':'Начать тест'} ${svg('arrow')}</button>${fin?'<button class="btn btn-outline" data-act="show-results">Посмотреть последний результат</button>':''}</div></div><div class="card"><h2>Что ты получишь после теста</h2><div class="timeline-mini" style="margin-top:18px"><div class="timeline-item"><div class="timeline-dot">01</div><div><strong>Ориентировочный уровень</strong><p>Предварительная оценка освоения заданий A1, A2 и B1</p></div></div><div class="timeline-item"><div class="timeline-dot">02</div><div><strong>Разбор неправильных ответов</strong><p>Правильные решения с объяснениями на русском</p></div></div><div class="timeline-item"><div class="timeline-dot">03</div><div><strong>Рекомендации для подготовки</strong><p>С каких тем начать и какие навыки усилить</p></div></div></div>${n&&!fin?`<div class="notice" style="margin-top:18px">Найдено ответов: ${n} из 44.${n===D.questions.length?' <strong>Можно рассчитать результат прямо сейчас без повторного теста.</strong>':''}</div>${n===D.questions.length?'<button class="btn btn-primary" data-act="finish-test" style="margin-top:12px">Восстановить результат по 44 ответам</button>':''}`:''}</div></div>`}
function diagnosticChoices(q){let arr=[...q.options];let hash=[...q.id+q.question].reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,7),off=hash%arr.length;return [...arr.slice(off),...arr.slice(0,off)]}
function takeTest(){let i=Math.max(0,Math.min(D.questions.length-1,filters.diagnosticIndex)),q=D.questions[i],value=state.diagnostic.answers[q.id],n=Object.keys(state.diagnostic.answers).length, passage=q.passage!==undefined?D.passages[q.passage]:null;return `<div class="quiz"><div class="row justify-between wrap" style="margin-bottom:17px"><a class="back-link" style="margin:0" href="#/диагностика">${svg('left','class="inline-icon"')} К описанию</a><span class="pill">${q.level} · ${q.area}</span></div><div class="card"><div class="row justify-between"><span class="question-count">Вопрос ${i+1} из ${D.questions.length}</span><span class="small text-muted">Ответов: ${n}</span></div><div style="margin:16px 0 10px">${pbar(i+1,D.questions.length)}</div>${passage?`<div class="passage"><h3>${passage.title}</h3>${esc(passage.text)}</div>`:''}<h2 class="question-title">${esc(q.question)}</h2><div class="options">${diagnosticChoices(q).map((opt,j)=>`<button class="option ${value===opt?'selected':''}" data-act="answer-test" data-id="${q.id}" data-option="${esc(opt)}"><span class="opt-letter">${String.fromCharCode(65+j)}</span>${esc(opt)}</button>`).join('')}</div><div class="quiz-nav"><button class="btn btn-outline" ${i===0?'disabled':''} data-act="test-prev">${svg('left')} Назад</button><button class="btn btn-primary" data-act="${i===D.questions.length-1?'finish-test':'test-next'}">${i===D.questions.length-1?'Завершить тест':'Следующий вопрос'} ${svg('arrow')}</button></div></div><div class="row wrap" style="margin-top:16px"><span class="small text-muted">Можно пропустить вопрос и вернуться к нему позже.</span><button class="btn btn-sm btn-outline" data-act="test-first-empty">К первому пропущенному</button></div></div>`}
function computeResults(){let all=D.questions;let res={};for(let level of ['A1','A2','B1']){let arr=all.filter(q=>q.level===level);res[level]={correct:arr.filter(q=>state.diagnostic.answers[q.id]===q.answer).length,total:arr.length};}let areas={};['Грамматика','Лексика','Чтение'].forEach(area=>{let arr=all.filter(q=>q.area===area);areas[area]={correct:arr.filter(q=>state.diagnostic.answers[q.id]===q.answer).length,total:arr.length}});let lvl=res.B1.correct/res.B1.total>=.72&&res.A2.correct/res.A2.total>=.72&&res.A1.correct/res.A1.total>=.7?'уверенная база B1 по проверенным заданиям':res.A2.correct/res.A2.total>=.65&&res.A1.correct/res.A1.total>=.7?'база A2 по проверенным заданиям':res.A1.correct/res.A1.total>=.65?'основа A1, есть темы для усиления':'начальный этап: восстановить базовые темы';return {res,areas,level:lvl,correct:all.filter(q=>state.diagnostic.answers[q.id]===q.answer).length,total:all.length,answered:Object.keys(state.diagnostic.answers).length}}
function resultsPage(){let result=state.diagnostic.result;if(!result)return diagnosticIntro();let pct=percent(result.correct,result.total),weak=Object.entries(result.areas).sort((a,b)=>percent(a[1].correct,a[1].total)-percent(b[1].correct,b[1].total))[0];return `${heading('Диагностика · результат','Твоя отправная точка','Результат показывает знания в представленных заданиях. Для полноценной оценки уровня нужны также аудирование, письмо и устная речь.')}<div class="grid g-2"><div class="card"><div class="result-row"><div class="score-circle" style="--score:${pct}%"><strong>${pct}%</strong></div><div><span class="eyebrow">ОТВЕТОВ ВЕРНО</span><h2>${result.correct} из ${result.total}</h2><p style="margin:8px 0 0">${result.answered} вопросов было заполнено.</p></div></div><div style="margin-top:22px"><span class="level-chip">${esc(result.level)}</span></div><p style="font-size:12px;margin:13px 0 0">Это не официальный результат ОГЭ и не подтверждённый CEFR-уровень.</p><div class="score-detail"><h3>Результаты по уровням заданий</h3>${Object.entries(result.res).map(([level,x])=>`<div class="result-area"><div><span class="semibold">${level}</span> ${pbar(x.correct,x.total)}</div><strong>${percent(x.correct,x.total)}%</strong></div>`).join('')}</div></div><div class="card"><h2>Что делать дальше</h2><div class="notice" style="margin:17px 0">В первую очередь обрати внимание на раздел «${esc(weak?.[0]||'Грамматика')}». Ошибки в нём помогут выбрать задания для повторения.</div><h3>Области знаний</h3>${Object.entries(result.areas).map(([area,x])=>`<div class="result-area"><div>${esc(area)} ${pbar(x.correct,x.total)}</div><strong>${percent(x.correct,x.total)}%</strong></div>`).join('')}<div class="quick-actions" style="margin-top:23px"><a class="btn btn-primary" href="#/план">Открыть маршрут ${svg('arrow')}</a><button class="btn btn-outline" data-act="toggle-review">${filters.reviewOpen?'Скрыть':'Разобрать'} ошибки</button></div></div></div>${filters.reviewOpen?`<div class="card" style="margin-top:18px"><h2>Разбор ответов</h2>${D.questions.filter(q=>state.diagnostic.answers[q.id]!==q.answer).map(q=>`<div class="review-item"><span class="pill gray">${q.level} · ${q.area}</span><div class="semibold" style="margin:9px 0">${esc(q.question)}</div><div class="small wrong-answer">Твой ответ: ${esc(state.diagnostic.answers[q.id]??'нет ответа')}</div><div class="small right-answer">Правильно: ${esc(q.answer)}</div><p class="small" style="margin:5px 0 0">${esc(q.explain)}</p></div>`).join('')||'<p>Все ответы правильные — отличный результат!</p>'}</div>`:''}<div class="quick-actions" style="margin-top:18px"><button class="btn btn-primary" data-act="export-data">Скачать резервную копию результата</button><button class="btn btn-outline" data-act="reset-test">Пройти диагностику заново</button><a class="btn btn-soft" href="#/диагностика">Обзор диагностики</a></div>`}
function grammarPage(){let q=filters.grammarSearch.toLowerCase().trim(),total=grammarTotal();return `${heading('Теория и практика','Грамматика','Все темы в одном месте. Отмечай изученные правила и проходи короткие тесты, где они доступны.',`<span class="pill">${learnedGrammar()}/${total} изучено</span>`)}<div class="toolbar"><label class="searchbox">${svg('search')}<input data-filter="grammar" placeholder="Найти тему: Present, Passive, вопросы…" value="${esc(filters.grammarSearch)}"></label></div><div class="grid g-2" style="margin-bottom:19px"><div class="mini-tile"><strong>${total} подтем</strong><small>Организованы в ${P.grammarGroups.length} разделов</small></div><div class="mini-tile"><strong>${Object.keys(P.rules).length} объяснений с тестами</strong><small>Остальные темы — в учебном каталоге, материал будет дополняться</small></div></div>${P.grammarGroups.map(g=>{let ts=g.topics.filter(t=>t.title.toLowerCase().includes(q)||g.name.toLowerCase().includes(q));if(!ts.length)return '';let n=g.topics.filter(t=>state.grammar[t.id]?.done).length;return `<details class="accordion" ${q||P.grammarGroups.indexOf(g)===0?'open':''}><summary><span>${esc(g.name)} <span class="pill gray" style="margin-left:7px">${n}/${g.topics.length}</span></span></summary><div class="accordion-body">${ts.map(t=>{let hasRule=!!P.rules[t.title],completed=!!state.grammar[t.id]?.done;return `<div class="topic-row"><div><div class="topic-name">${esc(t.title)}</div><div class="small text-muted">${hasRule?'Есть объяснение и проверка':'Тема в программе · урок разрабатывается'}</div></div><div class="topic-actions">${hasRule?`<a class="mini-btn" href="#/правило?id=${t.id}">Изучить</a>`:''}<button class="mini-btn ${completed?'done':''}" data-act="toggle-grammar" data-id="${t.id}" title="Отметка самостоятельного изучения">${completed?'✓ Изучено':'Отметить'}</button></div></div>`}).join('')}</div></details>`}).join('')}`}
function rulePage(){let id=param('id'),topic=P.grammarGroups.flatMap(g=>g.topics).find(x=>x.id===id);if(!topic)return grammarPage();let rule=P.rules[topic.title],saved=state.grammar[id]||{};return `<a class="back-link" href="#/грамматика">${svg('left','class="inline-icon"')} Вернуться к грамматике</a>${heading('Грамматика · правило',esc(topic.title),'Читай правило, сравни примеры и проверь понимание.')}${rule?`<div class="grid g-2"><div class="card"><h2>Когда употребляется</h2><p class="readable" style="margin-top:15px">${esc(rule.explain)}</p><div class="task-box"><strong>Формула</strong><p>${esc(rule.form)}</p></div><h3>Обрати внимание</h3><div class="notice" style="margin-top:10px">${esc(rule.tip)}</div></div><div class="card"><h2>Примеры</h2><div class="task-box"><strong>Утверждение</strong><p>${esc(rule.positive)}</p><strong>Отрицание</strong><p>${esc(rule.negative)}</p><strong>Вопрос</strong><p>${esc(rule.question)}</p></div><h3>Быстрая проверка</h3><p class="small" style="margin:7px 0 13px">${rule.check.length} вопроса, ответы проверяются сразу</p>${rule.check.map((q,i)=>`<div style="margin-bottom:15px"><div class="semibold" style="font-size:12px;margin-bottom:8px">${i+1}. ${esc(q[0])}</div><select class="select" style="width:100%" data-rule-choice="${i}"><option value="">Выбери ответ</option>${q[2].map(a=>`<option value="${esc(a)}">${esc(a)}</option>`).join('')}</select></div>`).join('')}<button class="btn btn-primary" data-act="check-rule" data-id="${id}">Проверить ответы</button><div id="rule-feedback" role="status" style="margin-top:12px"></div>${saved.best!==undefined?`<p class="small" style="margin-top:12px">Лучший результат: ${saved.best}%</p>`:''}</div></div>`:`<div class="card"><p>Тема включена в учебную программу. Подробное объяснение и проверочные задания пока готовятся.</p><a href="#/задания" class="btn btn-outline">Перейти к заданиям</a></div>`}<div class="quick-actions" style="margin-top:18px"><button class="btn ${saved.done?'btn-soft':'btn-outline'}" data-act="toggle-grammar" data-id="${id}">${svg('checkCircle')} ${saved.done?'Снять отметку «Изучено»':'Отметить правило как изученное'}</button></div>`}
function vocabPage(){let t=P.vocabulary.find(x=>x.id===filters.vocabTopic)||P.vocabulary[0];let rows=t.words.filter(x=>(x.en+' '+x.ru).toLowerCase().includes(filters.vocabSearch.toLowerCase())).filter(x=>filters.vocabStatus==='all'||(filters.vocabStatus==='new'?!state.vocab[x.id]:state.vocab[x.id]===filters.vocabStatus));let all=P.vocabulary.reduce((n,x)=>n+x.words.length,0);return `${heading('Слова и выражения','Тематический словарь','Учить, слушать произношение и возвращаться к сложным словам.',`<a href="#/глаголы" class="btn btn-outline">Неправильные глаголы ${svg('arrow')}</a>`)}<div class="grid g-3" style="margin-bottom:20px">${stat('В стартовом словаре',all,'book')}${stat('Изучено',learnedWords(),'checkCircle','green')}${stat('Нужно повторить',Object.values(state.vocab).filter(v=>v==='hard').length,'refresh','orange')}</div><div class="vocab-layout"><div class="topic-sidebar">${P.vocabulary.map(g=>`<button class="topic-tab ${t.id===g.id?'active':''}" data-act="vocab-topic" data-id="${g.id}"><span>${esc(g.title)}</span><small>${g.words.filter(w=>state.vocab[w.id]==='known').length}/${g.words.length}</small></button>`).join('')}</div><div><div class="card"><div class="section-head"><div><h2>${esc(t.title)}</h2><p class="small" style="margin:4px 0 0">${t.words.length} единиц в теме</p></div><a class="btn btn-soft btn-sm" href="#/карточки?topic=${t.id}">${svg('sparkles')} Карточки</a></div><div class="toolbar"><label class="searchbox">${svg('search')}<input data-filter="vocab" placeholder="Слово или перевод" value="${esc(filters.vocabSearch)}"></label><select class="select" data-act="vocab-status"><option value="all" ${filters.vocabStatus==='all'?'selected':''}>Все слова</option><option value="new" ${filters.vocabStatus==='new'?'selected':''}>Не изучены</option><option value="known" ${filters.vocabStatus==='known'?'selected':''}>Изучены</option><option value="hard" ${filters.vocabStatus==='hard'?'selected':''}>Повторить</option></select></div><div class="vocab-list">${rows.length?rows.map(w=>`<div class="word-row"><strong>${esc(w.en)}</strong><span>${esc(w.ru)}</span><div class="word-buttons"><button class="icon-btn" data-act="speak" data-speak="${esc(w.en)}" title="Прослушать произношение" aria-label="Прослушать ${esc(w.en)}">${svg('volume')}</button><button class="icon-btn ${state.vocab[w.id]==='hard'?'active':''}" data-act="word-status" data-id="${w.id}" data-status="hard" title="Повторить">${svg('refresh')}</button><button class="icon-btn ${state.vocab[w.id]==='known'?'active':''}" data-act="word-status" data-id="${w.id}" data-status="known" title="Изучено">${svg('check')}</button></div></div>`).join(''):'<div class="empty">Нет слов по выбранному фильтру.</div>'}</div></div><div class="notice warning" style="margin-top:16px">Это стартовый словарь из ${all} учебных записей, а не полный официальный перечень ФИПИ. Лексическая база будет расширяться с учётом диагностики и практики.</div></div></div>`}
function flashPage(){let t=P.vocabulary.find(x=>x.id===param('topic'))||P.vocabulary[0];filters.flashIndex=Math.min(filters.flashIndex,t.words.length-1);let w=t.words[filters.flashIndex];return `<a class="back-link" href="#/словарь">${svg('left','class="inline-icon"')} К словарю</a>${heading('Повторение слов','Карточки · '+esc(t.title),'Нажми «Показать перевод», попробовав сначала вспомнить значение самостоятельно.') }<div class="card" style="max-width:650px"><div class="row justify-between" style="margin-bottom:18px"><span class="pill">Карточка ${filters.flashIndex+1}/${t.words.length}</span><span class="pill ${state.vocab[w.id]==='known'?'green':'gray'}">${state.vocab[w.id]==='known'?'Изучено':'Повторение'}</span></div><div class="flashcard"><div class="hint">АНГЛИЙСКИЙ</div><div class="en">${esc(w.en)}</div><button class="icon-btn" data-act="speak" data-speak="${esc(w.en)}" title="Произношение">${svg('volume')}</button>${filters.flashShow?`<div class="ru">${esc(w.ru)}</div>`:`<button data-act="flash-flip" class="btn btn-light">Показать перевод</button>`}</div><div class="quiz-nav"><button class="btn btn-outline" data-act="flash-prev" ${filters.flashIndex===0?'disabled':''}>${svg('left')} Предыдущая</button><div class="quick-actions"><button class="btn btn-outline" data-act="flash-status" data-status="hard">Повторить</button><button class="btn btn-primary" data-act="flash-status" data-status="known">Знаю ${svg('check')}</button></div></div></div>`}
function verbsPage(){let vs=P.verbs.filter(v=>(v.v1+' '+v.v2+' '+v.v3+' '+v.ru).toLowerCase().includes(filters.verbSearch.toLowerCase()));return `${heading('Частотные глаголы','Неправильные глаголы','Учебный список с формами V1, V2 и V3. Включает допустимые варианты BrE и AmE.',`<span class="pill">${learnedVerbs()}/${P.verbs.length} изучено</span>`)}<div class="grid g-2" style="margin-bottom:20px"><div class="card"><div class="section-head"><h2>Тренировка форм</h2><span class="pill">V1 → V2 / V3</span></div><p class="small">Напиши одну из правильных форм. В некоторых глаголах возможны варианты через косую черту.</p><div class="row wrap" style="margin:12px 0"><select class="select" data-act="verb-stage"><option value="v2" ${filters.verbStage==='v2'?'selected':''}>Вторая форма (V2)</option><option value="v3" ${filters.verbStage==='v3'?'selected':''}>Третья форма (V3)</option></select><button data-act="next-verb" class="btn btn-sm btn-outline">Другой глагол</button></div><div id="verb-card"></div></div><div class="card"><h2 style="margin-bottom:13px">Как выучить надолго</h2><div class="timeline-mini"><div class="timeline-item"><div class="timeline-dot">1</div><div><strong>Учи группами по 8–12</strong><p>Особенно похожие модели: sing–sang–sung, drink–drank–drunk</p></div></div><div class="timeline-item"><div class="timeline-dot">2</div><div><strong>Повторяй в контексте</strong><p>She went yesterday. / She has gone home.</p></div></div><div class="timeline-item"><div class="timeline-dot">3</div><div><strong>Возвращайся к ошибкам</strong><p>Для экзамена важно узнавать глаголы в заданиях, а не просто перечислять формы</p></div></div></div></div></div><div class="card"><div class="section-head"><h2>Все формы</h2><span class="pill">${P.verbs.length} глаголов</span></div><div class="toolbar"><label class="searchbox">${svg('search')}<input data-filter="verbs" value="${esc(filters.verbSearch)}" placeholder="Найти глагол или перевод"></label></div><div class="table-wrap"><table class="verb-table"><thead><tr><th>V1</th><th>V2</th><th>V3</th><th>Перевод</th><th>Готово</th></tr></thead><tbody>${vs.map(v=>`<tr><td><strong>${esc(v.v1)}</strong></td><td>${esc(v.v2)}</td><td>${esc(v.v3)}</td><td>${esc(v.ru)}</td><td><button class="icon-btn ${state.verbs[v.id]?'active':''}" data-act="toggle-verb" data-id="${v.id}" aria-label="${state.verbs[v.id]?'Снять отметку':'Отметить изученным'}">${svg('check')}</button></td></tr>`).join('')}</tbody></table></div><p class="small" style="margin-top:12px">read–read–read пишется одинаково, но V2/V3 произносится /red/. Lie–lay–lain здесь означает «лежать».</p></div>`}
let currentVerbIndex=0;
function verbCard(){let v=P.verbs[currentVerbIndex%P.verbs.length];return `<div class="task-box"><span class="eyebrow" style="margin:0">ПЕРВАЯ ФОРМА · ${esc(v.ru)}</span><div style="font-size:23px;font-weight:800;margin:8px 0;color:var(--indigo)">${esc(v.v1)}</div><div class="row wrap"><input id="verb-answer" class="field" style="max-width:220px" placeholder="Впиши ${filters.verbStage.toUpperCase()}" autocomplete="off"><button class="btn btn-primary btn-sm" data-act="check-verb">Проверить</button></div><div id="verb-feedback" class="small" role="status" style="margin-top:9px"></div></div>`}
const practices=[
{id:'p1',label:'Грамматика: времена',section:'Грамматика и лексика',questions:[['She ___ to London last summer.','went',['went','goes','has gone'],'Past Simple: last summer'],['He has already ___ the letter.','written',['wrote','write','written'],'Present Perfect: have/has + V3'],['We ___ dinner when the lights went out.','were having',['had','were having','have'],'Фоновое длительное действие — Past Continuous'],['They ___ to school on Sundays.','don’t go',['don’t go','doesn’t go','aren’t go'],'Present Simple, отрицание с they'],['If I ___ time, I’ll help you.','have',['will have','had','have'],'В if-части First Conditional — Present Simple']]},
{id:'p2',label:'Словообразование',section:'Грамматика и лексика',questions:[['She is a very ___ student. (CARE)','careful',['care','careful','carefully'],'Нужно прилагательное перед существительным'],['His ___ surprised us. (DECIDE)','decision',['decide','decision','decisive'],'His + существительное'],['This book is really ___. (INTEREST)','interesting',['interested','interesting','interest'],'Интересный предмет → interesting'],['Please speak more ___. (SLOW)','slowly',['slow','slowness','slowly'],'Нужно наречие образа действия'],['It was an ___ day. (FORGET)','unforgettable',['forgetful','forgotten','unforgettable'],'Незабываемый — unforgettable']]},
{id:'p3',label:'Чтение: три варианта',section:'Чтение',passage:'Alex wanted to join the school debate club, but he was nervous about speaking in public. His friend Mia suggested attending one meeting without participating. Alex followed her advice. He found the atmosphere friendly, so he decided to join the club the following week. Three months later, he gave a short speech at a school event.',questions:[['Alex was immediately confident about speaking in public.','False',['True','False','Not stated'],'В тексте он нервничал.'],['Mia recommended visiting a meeting as an observer.','True',['True','False','Not stated'],'Она предложила прийти, не участвуя.'],['The club charged a monthly fee.','Not stated',['True','False','Not stated'],'Про взносы не сообщается.'],['Alex eventually spoke at a school event.','True',['True','False','Not stated'],'Через три месяца он выступил.']]},
{id:'p4',label:'Лексика в контексте',section:'Грамматика и лексика',questions:[['I don’t want to ___ money on things I don’t need.','waste',['waste','earn','keep'],'Waste money — тратить деньги зря'],['He decided to ___ photography as a hobby.','take up',['put off','take up','get off'],'Take up — начать заниматься'],['A person who is always honest is ___.','trustworthy',['selfish','trustworthy','rude'],'Trustworthy — заслуживающий доверия'],['Can you ___ my cat while I’m away?','look after',['look up','look after','look for'],'Look after — присматривать'],['They want to ___ air pollution.','reduce',['rise','reduce','increase'],'Reduce — уменьшить']]}
];
function practicePage(){let results=state.practice;return `${heading('Задания в формате ОГЭ','Тренажёр','Короткие авторские тренировки по отдельным навыкам. Полные варианты берём из материалов ФИПИ.')}<div class="grid g-2"><div class="card"><div class="section-head"><h2>Доступные тренировки</h2><span class="pill">${practices.length} набора</span></div>${practices.map(p=>`<a class="lesson-link" style="margin:0 0 11px" href="#/задания?id=${p.id}"><div><strong>${esc(p.label)}</strong><p>${p.questions.length} вопросов · ${esc(p.section)}</p>${results[p.id]!==undefined?`<span class="pill green">Лучший результат: ${results[p.id]}%</span>`:''}</div>${svg('arrow','width="17"')}</a>`).join('')}</div><div class="grid" style="align-content:start;gap:17px"><div class="card"><h2>Письмо</h2><p style="font-size:12px;margin-top:12px">Потренируйся отвечать на три вопроса друга, сохраняя черновик.</p><a href="#/письмо" class="btn btn-soft">Открыть редактор ${svg('arrow')}</a></div><div class="card"><h2>Говорение</h2><p style="font-size:12px;margin-top:12px">Подготовь монолог и запиши ответ голосом прямо в браузере.</p><a href="#/говорение" class="btn btn-soft">Запись ответа ${svg('arrow')}</a></div><div class="notice warning">Здесь представлены демонстрационные авторские тренировки. Для оригинальных экзаменационных аудиозаписей и вариантов используй официальный архив ФИПИ в разделе «Материалы».</div></div></div>`}
let practiceAnswers={};
function practiceDetail(){let p=practices.find(x=>x.id===param('id'))||practices[0];let feedback=filters.practiceChecked===p.id;return `<a class="back-link" href="#/тренажёр">${svg('left','class="inline-icon"')} К тренажёру</a>${heading('Практика · '+esc(p.section),esc(p.label),'Выбери вариант для каждого вопроса и нажми «Проверить».')}<div class="card quiz">${p.passage?`<div class="passage"><h3>Прочитай текст</h3>${esc(p.passage)}</div>`:''}${p.questions.map((q,i)=>`<div style="margin-bottom:22px"><span class="muted-eyebrow">ВОПРОС ${i+1}</span><div class="semibold" style="margin:6px 0 11px;font-size:14px">${esc(q[0])}</div><div class="options">${q[2].map((opt,j)=>{let chosen=practiceAnswers[p.id]?.[i]===opt;return `<button data-act="practice-answer" data-id="${p.id}" data-index="${i}" data-answer="${esc(opt)}" class="option ${feedback?opt===q[1]?'correct':chosen?'wrong':'':chosen?'selected':''}" ${feedback?'disabled':''}><span class="opt-letter">${String.fromCharCode(65+j)}</span>${esc(opt)}</button>`}).join('')}</div>${feedback?`<p class="small" style="margin-top:8px;color:#777b8e">${esc(q[3])}</p>`:''}</div>`).join('')}${feedback?`<div class="notice success">Результат: ${p.questions.filter((q,i)=>practiceAnswers[p.id]?.[i]===q[1]).length} из ${p.questions.length}. Можно повторить упражнения.</div><button class="btn btn-outline" style="margin-top:15px" data-act="practice-retry" data-id="${p.id}">Повторить тренировку</button>`:`<div class="row wrap"><button class="btn btn-primary" data-act="practice-check" data-id="${p.id}">Проверить ответы</button><span class="small text-muted">Ответов: ${Object.keys(practiceAnswers[p.id]||{}).length} из ${p.questions.length}</span></div>`}</div>`}
function examPage(){return `${heading('Формат экзамена','Тренажёр ОГЭ','Все разделы экзамена, авторские тренировки и ссылки на официальные задания ФИПИ.') }<div class="grid g-3" style="margin-bottom:20px">${P.examSections.map(s=>`<div class="card"><div class="stat-icon" style="margin-bottom:15px">${svg(s.icon)}</div><span class="pill gray">Задания ${esc(s.numbers)}</span><h3 style="margin:13px 0 7px">${esc(s.name)}</h3><p class="small" style="min-height:50px">${esc(s.summary)}</p><div class="checklist">${s.skills.map(x=>`<div class="checkline">${svg('check','class="inline-icon"')} ${esc(x)}</div>`).join('')}</div></div>`).join('')}</div><div class="grid g-2"><div class="card"><h2>Тренировочные задания</h2><p style="font-size:12px;margin:12px 0 20px">Времена, формы слов, чтение и лексика. Проверка и объяснение ошибок.</p><a class="btn btn-primary" href="#/задания">Перейти к заданиям ${svg('arrow')}</a></div><div class="card"><h2>Официальные образцы</h2><p style="font-size:12px;margin:12px 0 20px">Демоверсия письменной и устной частей, аудио, кодификатор и критерии проверки.</p><a class="btn btn-outline" href="${C.official.zip}" target="_blank" rel="noopener noreferrer">Открыть архив ФИПИ ${svg('download')}</a></div></div>`}
function writingPage(){let count=(state.writing.text.trim().match(/\b[\w]+(?:['’\-][\w]+)*\b/g)||[]).length;let asks=['Я ответила на первый вопрос','Я ответила на второй вопрос','Я ответила на третий вопрос','Я использовала подходящие обращение и прощание','Я проверила грамматику и орфографию'];return `<a class="back-link" href="#/тренажёр">${svg('left','class="inline-icon"')} Назад</a>${heading('Практика письма','Электронное письмо','Редактор сохраняет черновик на этом устройстве. Оценка по критериям учителя пока не подключена.') }<div class="grid g-2"><div class="card"><h2>Задание</h2><div class="task-box"><strong>You have received an email from your English-speaking pen friend Sam.</strong><p>“Our school is organising a sports day next month. I want to try something new. What sports do you enjoy? How often do you do sports? Do you think school sports events are important? Why?”</p><p>Write an email to Sam and answer the three questions.</p></div><div class="notice warning">Ориентируйся на 100–120 слов и обязательно сверяй требования к объёму и оцениванию с действующей демоверсией ФИПИ.</div><h3 style="margin-top:18px">Самопроверка</h3><div class="checklist" style="margin-top:12px">${asks.map((x,i)=>`<label class="checkline"><input type="checkbox" data-act="writing-check" data-index="${i}" ${state.writing.checks[i]?'checked':''}>${x}</label>`).join('')}</div></div><div class="card"><div class="section-head"><h2>Твой ответ</h2><span class="pill ${count>=100&&count<=120?'green':'gray'}">${count} слов</span></div><textarea class="field writing-box" id="writing-text" placeholder="Hi Sam,&#10;&#10;Thanks for your email! ..." spellcheck="true">${esc(state.writing.text)}</textarea><div class="row justify-between wrap" style="margin-top:14px"><span class="small text-muted">Сохранение по мере набора текста</span><button class="btn btn-outline btn-sm" data-act="download-writing">${svg('download')} Скачать текст</button></div><div class="notice" style="margin-top:15px">Автоматическая проверка грамматики и оценивание письма по критериям ФИПИ в этой версии ещё не реализованы.</div></div></div>`}
function speakingPage(){return `<a class="back-link" href="#/тренажёр">${svg('left','class="inline-icon"')} Назад</a>${heading('Устная часть','Тренировка говорения','Запиши короткий монолог. Запись остаётся в браузере до ухода со страницы, её можно скачать.') }<div class="grid g-2"><div class="card"><span class="pill">Учебный монолог</span><h2 style="margin:13px 0">Talk about your school life</h2><div class="task-box"><strong>Remember to say:</strong><p>• what your favourite school subjects are and why</p><p>• what you usually do after school</p><p>• whether you prefer studying alone or with friends, and why</p><p>• what you would like to improve at school</p></div><p class="small">Попробуй сказать 10–12 связных фраз, используя слова-связки. Это авторская практика, а не официальное экзаменационное задание.</p></div><div class="card"><h2>Запись ответа</h2><p class="small" style="margin-top:12px">Разреши браузеру доступ к микрофону. Он может быть доступен только на HTTPS или localhost.</p><div id="recorder-ui" class="task-box"><div class="row wrap"><button class="btn btn-primary" data-act="record-toggle" id="record-button">${svg('mic')} Начать запись</button><span class="pill gray" id="record-status">Не записывается</span></div></div><div id="record-audio"></div><div class="notice warning">Аудио никуда не отправляется автоматически: Telegram и облачное хранилище не подключены. Для проверки преподавателем скачай файл и отправь отдельно.</div></div></div>`}
function resourcesPage(){let res=[['Документы ФИПИ — ОГЭ 2027','Проектные демоверсии, спецификации, кодификаторы',C.official.documents],['Архив английского языка ОГЭ 2027','Письменная и устная части, демонстрационные аудиофайлы',C.official.zip],['Открытый банк заданий ФИПИ','Практика официальных типов заданий',C.official.bank],['Навигатор подготовки ФИПИ','Рекомендации по самостоятельной подготовке',C.official.navigator],['British Council — LearnEnglish Teens','Дополнительные языковые тренировки, не официальный ОГЭ','https://learnenglishteens.britishcouncil.org/'],['Cambridge English — Learning English','Общая языковая практика, не экзаменационные задания ФИПИ','https://www.cambridgeenglish.org/learning-english/']];return `${heading('Надёжная база для занятий','Материалы подготовки','Официальные документы ФИПИ и дополнительные учебные ресурсы с указанием назначения.') }<div class="notice" style="margin-bottom:18px">На октябрь 2026 года документы 2027 года опубликованы как проекты. Перед экзаменом следует проверить, не была ли опубликована окончательная редакция.</div><div class="grid g-2">${res.map((r,i)=>`<a class="resource-card" href="${r[2]}" target="_blank" rel="noopener noreferrer"><div class="row"><span class="stat-icon ${i>3?'orange':''}">${svg(i===1?'headphones':i===2?'layers':i===3?'book':'download')}</span><span><strong>${esc(r[0])}</strong><small>${esc(r[1])}</small></span></div>${svg('arrow','width="17" height="17"')}</a>`).join('')}</div><div class="card" style="margin-top:20px"><h2>Что уже включено в сайт</h2><p class="small" style="margin-top:10px">Учебная программа на 29 недель, каталог грамматики, стартовая подборка 400 тематических лексических единиц, 119 неправильных глаголов, авторская диагностика и тренировочные задания. Официальные аудиозаписи не встроены — ссылка ведёт к оригинальному архиву ФИПИ.</p><div class="notice warning">Встраивание/копирование дополнительных материалов и аудио будем делать с учётом разрешений правообладателей и правильного указания источников. Аудио из архива Даниила к этому курсу не относится и не перенесено.</div></div>`}
function reportsPage(){
 const week=reportPreview('week'),month=reportPreview('month');
 const fmt=(report)=>report?.metrics?.accuracy===null?'нет данных':report?.metrics?.accuracy+'%';
 const alert='<div class="notice warning" style="margin-bottom:17px"><strong>Предпросмотр на этом устройстве.</strong> Автоматическая отправка в Telegram требует подключённых Supabase и расписания. Здесь показан локальный расчёт по синхронизированному журналу этого устройства.</div>';
 return `${heading('Аналитика без лишних уведомлений','Отчёты для семьи','Только два регулярных сообщения: каждую неделю по понедельникам и 1-го числа каждого месяца. Никаких Telegram-сообщений после отдельных заданий.')}${alert}<div class="grid g-3" style="margin-bottom:20px">${stat('Учебные дни за прошлую неделю',week.metrics.studyDays+'/3','calendar','green')}${stat('Точность за прошлую неделю',fmt(week),'target')}${stat('Точность за прошлый месяц',fmt(month),'chart','orange')}</div><div class="grid g-2"><section class="card report-card"><div class="section-head"><h2>Отчёт за неделю</h2><span class="pill">По понедельникам</span></div><p class="small" style="margin:9px 0">${esc(week.period.label)}. Анализ по пройденным темам, ошибкам и трём учебным дням.</p><pre class="report-message">${esc(week.text)}</pre><button class="btn btn-outline btn-sm" data-act="copy-report" data-period="week">${svg('download')} Скопировать текст</button></section><section class="card report-card"><div class="section-head"><h2>Отчёт за месяц</h2><span class="pill">1-го числа</span></div><p class="small" style="margin:9px 0">${esc(month.period.label)}: сравнение с ${esc(month.period.previous.label)}. Если данных мало, проценты не додумываются.</p><pre class="report-message">${esc(month.text)}</pre><button class="btn btn-outline btn-sm" data-act="copy-report" data-period="month">${svg('download')} Скопировать текст</button></section></div><div class="card" style="margin-top:20px"><h2>Что отслеживается</h2><p class="small" style="margin-top:11px">Сайт сохраняет в журнал попытки (в том числе незачтённые), категории ошибок: грамматика, словарь, чтение, аудирование, словообразование и неправильные глаголы; изученные темы; результаты тестов и фактические даты занятий.</p><p class="small" style="margin-top:8px">Письменные и устные ответы не оцениваются автоматически: в статистике такие работы не считаются проверенными учителем. Отметки слов означают только самооценку «изучено», а не независимую проверку владения словом.</p></div>`;
}
function cloudPanel(){
 const c=window.OGE_CLOUD?.status()||{enabled:false,connected:false};
 if(!c.enabled)return `<div class="notice" style="margin-top:14px">Для синхронизации прогресса и автоматических Telegram-отчётов необходимо заполнить параметры облака в config.js и развернуть защищённую серверную функцию из папки supabase. До подключения данные остаются только в этом браузере.</div>`;
 if(c.connected)return `<div class="task-box" style="margin-top:16px"><strong>${c.syncedAt&&!c.error?'Прогресс сохранён в облаке':'Сохранение в облако ещё не подтверждено'}</strong><p class="small">Аккаунт Кристины: ${esc(c.email)}. ${c.syncedAt&&!c.error?'Последнее успешное сохранение: '+esc(new Date(c.syncedAt).toLocaleString('ru-RU')):'Проверь статус и нажми «Синхронизировать».'}</p>${c.error?`<div class="notice warning">${esc(c.error)}</div>`:''}<div class="row wrap"><button data-act="cloud-sync" class="btn btn-outline btn-sm">Синхронизировать</button><button data-act="cloud-invite" class="btn btn-primary btn-sm">Открыть доступ для семьи</button><button data-act="cloud-revoke" class="btn btn-outline btn-sm">Закрыть доступ наблюдателям</button><button data-act="cloud-logout" class="btn btn-outline btn-sm">Выйти</button></div><div id="cloud-code-result" class="small" style="margin-top:13px;overflow-wrap:anywhere">${c.viewerCode?`<strong>Одноразовый код (72 часа): ${esc(c.viewerCode)}</strong><p>Передай этот код только своему наблюдателю.</p>`:"Нажми «Открыть доступ для семьи», затем передай код тому, кто будет следить за подготовкой. Он действует 72 часа."} <a href="./viewer.html" target="_blank" rel="noopener">Страница наблюдения →</a></div></div>`;
 return `<div class="task-box" style="margin-top:16px"><strong>Облачное сохранение: аккаунт Кристины</strong><p class="small">Сначала на компьютере Кристины скачай резервную копию в настройках. Затем создай её аккаунт и войди: сайт объединит старый прогресс с облачным. Для просмотра взрослому нужен отдельный аккаунт на странице наблюдения.</p><label class="small" for="cloud-email">Почта</label><input id="cloud-email" class="field" type="email" autocomplete="email" placeholder="Имя@почта.ru"><label class="small" for="cloud-password">Пароль</label><input id="cloud-password" class="field" type="password" autocomplete="current-password" placeholder="Не меньше 8 символов">${c.error?`<p class="small">${esc(c.error)}</p>`:''}<div class="row wrap" style="margin-top:12px"><button class="btn btn-primary btn-sm" data-act="cloud-login">Войти</button><button class="btn btn-outline btn-sm" data-act="cloud-register">Создать аккаунт</button></div></div>`;
}
function settingsPage(){return `${heading('Данные и интеграции','Настройки кабинета','Прогресс сохраняется в браузере и при входе в аккаунт Кристины — в защищённой облачной базе.') }<div class="grid g-2"><div class="card"><h2>Сохранение прогресса</h2><p class="small" style="margin-top:13px">Все отметки слов, недель, результатов тестов и черновик письма остаются в этом браузере. Чтобы переносить результаты между устройствами, войди в аккаунт Кристины ниже. Перед первым входом рекомендуется скачать резервную копию на исходном компьютере.</p><div class="quick-actions"><button class="btn btn-primary" data-act="export-data">${svg('download')} Скачать резервную копию</button><label class="btn btn-outline" style="cursor:pointer">${svg('upload')} Восстановить из файла<input type="file" id="restore-file" accept="application/json,.json" hidden></label></div><hr class="line"><button class="btn btn-danger btn-sm" data-act="reset-all">${svg('trash')} Сбросить данные кабинета</button></div><div class="card"><h2>Telegram-отчёты</h2><div class="row" style="margin:15px 0"><span class="pill orange">Не подключено</span><span class="small text-muted">Ожидает настройки сервера</span></div><p class="small">По понедельникам: отчёт за прошлую неделю. Каждого 1-го числа: сравнение двух предыдущих месяцев. Уведомлений после отдельного задания не будет. Ссылка не подтверждает chat_id и message_thread_id, их нужно проверить при подключении.</p><a class="resource-card" href="${C.telegram.discussionUrl}" target="_blank" rel="noopener noreferrer"><div class="row">${svg('mail')}<span><strong>Telegram: только недельные и месячные отчёты</strong><small>${esc(C.telegram.discussionUrl)}</small></span></div>${svg('arrow')}</a><p class="small" style="margin:16px 0 0"><a href="#/отчёты">Посмотреть предварительный отчёт на сайте →</a></p>${cloudPanel()}<p class="small" style="margin:16px 0 0">Облачная база готова, но передача начнётся после входа Кристины. Пароль нельзя передавать другому человеку. Данные Даниила не используются.</p></div></div><div class="notice warning" style="margin-top:18px">Перенос старого теста возможен только в том же браузере и по тому же адресу сайта, где он проходился, или из резервной копии JSON. Не очищай данные браузера до подтверждения облачной синхронизации. Telegram-отчёты ещё не подключены.</div>`}
function localISO(){const d=localStartToday();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function sessionId(wid,i){return wid+'-s'+i}
function weekSessionsDone(wid){return L.sessions.filter((s,i)=>state.sessions?.[sessionId(wid,i)]?.passed).length}
function weekDayCount(wid){return (state.weekStudyDays?.[wid]||[]).length}
function weekComplete(wid){return weekSessionsDone(wid)===3&&weekDayCount(wid)>=3}
function wordsCount(value){return (String(value||'').trim().match(/[A-Za-z]+(?:['’\-][A-Za-z]+)*/g)||[]).length}
function weekOverview(w,i){return `<div class="study-week-status card"><div class="row justify-between wrap"><div><span class="eyebrow">ОБЯЗАТЕЛЬНЫЙ МАРШРУТ</span><h2>${weekComplete(w.id)?'Неделя завершена':'3 занятия · 3 разных дня'}</h2><p class="small">${weekSessionsDone(w.id)} из 3 занятий зачтено · ${weekDayCount(w.id)} из 3 дней посещения</p></div><span class="pill ${weekComplete(w.id)?'green':'orange'}">${weekComplete(w.id)?'Цель достигнута':'В процессе'}</span></div>${pbar(weekSessionsDone(w.id)+Math.min(weekDayCount(w.id),3),6)}<div class="session-grid">${L.sessions.map((s,j)=>{let item=state.sessions?.[sessionId(w.id,j)],passed=!!item?.passed;return `<a class="session-tile ${passed?'session-done':''}" href="#/урок?week=${w.id}&session=${j}"><div class="session-number">${passed?svg('check'):j+1}</div><div><strong>${esc(s.name)}</strong><span>${esc(s.short)}</span><small>${esc(s.minutes)} минут · ${esc(s.hint)} ${item?.best!==undefined?'· лучший результат: '+item.best+'%':''}</small></div>${svg('right','class="session-arrow"')}</a>`}).join('')}</div><p class="small study-note">Для завершения недели нужно пройти все три занятия и заниматься минимум в три разные даты. Повторение пройденного урока в другой день также учитывается. Письменные ответы сохраняются, но не оцениваются автоматически по критериям ФИПИ.</p></div>`}
function lessonsPage(){let wi=weekNow(),w=P.weeks[wi],done=P.weeks.filter(x=>weekComplete(x.id)).length;let next=L.sessions.findIndex((s,i)=>!state.sessions?.[sessionId(w.id,i)]?.passed);return `${heading('Самостоятельная подготовка','Мои занятия','Три полноценных занятия каждую неделю. Проходи материал, выполняй задания и возвращайся к ошибкам.') }<section class="study-hero"><div><span class="eyebrow">ТВОЯ НЕДЕЛЯ · ${rangeWeek(wi)}</span><h2>Неделя ${wi+1}: ${esc(w.title)}</h2><p>Грамматика: ${esc(w.grammar)}<br>Словарь: ${esc(w.vocab)}<br>Экзаменационный навык: ${esc(w.skill)}</p><a class="btn btn-light" href="#/урок?week=${w.id}&session=${next===-1?0:next}"> ${svg('play')} ${next===-1?'Повторить занятие':'Продолжить обучение'}</a></div><div class="study-count"><strong>${weekSessionsDone(w.id)}/3</strong><span>занятий завершено</span><small>${weekDayCount(w.id)}/3 разных дня</small></div></section>${weekOverview(w,wi)}<div class="grid g-2" style="margin-top:18px"><a href="#/план" class="card study-link"><strong>${svg('calendar')} Весь календарь</strong><p>29 недель, темы и прогресс: ${done}/29 завершено</p><span>Открыть ${svg('arrow','class="inline-icon"')}</span></a><a href="#/повторение" class="card study-link"><strong>${svg('refresh')} Дополнительная практика</strong><p>Слова, глаголы, ошибки и ранее пройденные занятия</p><span>Повторить ${svg('arrow','class="inline-icon"')}</span></a></div>`}
function lessonPage(){const wid=param('week')||P.weeks[weekNow()].id, wi=P.weeks.findIndex(x=>x.id===wid);if(wi<0)return lessonsPage();const si=Number(param('session'));if(!Number.isInteger(si)||si<0||si>2)return lessonsPage();const s=L.sessions[si],w=P.weeks[wi],id=sessionId(wid,si),topic=L.vocabTopic(wi),qs=L.questions(wi,s.kind),stored=state.sessions?.[id]||{},draft=state.sessionDrafts?.[id]||'',checked=lessonFeedback?.id===id&&lessonFeedback?.done,answers=lessonAnswers[id]||{},answersCount=Object.keys(answers).length,read=L.reading(wi),listen=L.listen(wi);return `<a class="back-link" href="#/неделя?id=${wid}">${svg('left','class="inline-icon"')} План недели ${wi+1}</a>${heading('НЕДЕЛЯ '+(wi+1)+' · ЗАНЯТИЕ '+(si+1),esc(s.name),'Ориентир '+s.minutes+' минут. Здесь можно сохранить черновик и повторить занятие даже после зачёта.',`<span class="pill ${stored.passed?'green':'orange'}">${stored.passed?'Зачтено':'В процессе'}</span>`)}<div class="study-steps"><span>1. Изучить материал</span><span>2. Пройти упражнения</span><span>3. Написать ответ</span></div><div class="card study-material"><div class="section-head"><h2>1 · Изучаем материал</h2><span class="pill">15–20 минут</span></div><div class="lesson-guide"><span class="pill gray">Тема: ${esc(window.OGE_GUIDES?.[wi]?.title||w.title)}</span><p>${esc(window.OGE_GUIDES?.[wi]?.explain||w.grammar)}</p><div class="lesson-example"><small>ПРИМЕР</small><div>${esc(window.OGE_GUIDES?.[wi]?.example||'')}</div></div><p class="small"><strong>Обрати внимание:</strong> ${esc(window.OGE_GUIDES?.[wi]?.mistake||'Проверь контекст перед выбором ответа.')}</p></div>${s.kind==='grammar'?`<p>Тема недели: <strong>${esc(w.grammar)}</strong>. Начни с объяснения и составь в тетради 4 примера с этой конструкцией. Изученные правила доступны в отдельном разделе.</p><a class="btn btn-outline" href="#/грамматика">Открыть правила ${svg('arrow')}</a><div class="notice">Чтобы выбрать нужное правило, используй поиск по названию темы. Материал этой недели разобран выше. Для дополнительной практики можно открыть каталог правил и мини-тестов.</div>`:s.kind==='reading'?`<p>Лексическая тема: <strong>${esc(topic.title)}</strong>. Повтори не меньше 15 слов, затем прочитай текст и выполни задания True / False / Not stated.</p><div class="lesson-wordcloud">${topic.words.slice(0,15).map(x=>`<span title="${esc(x.ru)}">${esc(x.en)}</span>`).join('')}</div><div class="row wrap" style="margin-top:16px"><a class="btn btn-outline" href="#/словарь">Открыть весь словарь</a><a class="btn btn-soft" href="#/карточки?topic=${topic.id}">Карточки для повторения</a></div><div class="passage" style="margin-top:19px"><h3>Прочитай текст</h3><p class="study-english-text">${esc(read.text)}</p></div>`:`<p>Фокус недели: <strong>${esc(w.skill)}</strong>. Сначала выполни грамматическую часть. Затем прослушай короткое авторское сообщение и ответь на три вопроса.</p><div class="audio-training"><div><strong>${svg('headphones')} Тренировка аудирования</strong><p class="small">Английская речь воспроизводится синтезатором браузера. Это не официальная аудиозапись ОГЭ. Прослушай сообщение без текста два раза.</p></div><div class="row wrap"><button class="btn btn-primary" data-act="listen-session" data-week="${wi}">${svg('play')} Прослушать</button><button class="btn btn-outline" data-act="show-transcript">Показать текст</button></div><div id="lesson-transcript" class="notice hidden">${esc(listen.text)}</div></div>`}</div><div class="card study-material"><div class="section-head"><h2>2 · Проверь знания</h2><span class="pill">${qs.length} вопросов · порог 70%</span></div><p class="small">В каждом задании выбери один ответ. Ошибки и объяснения появятся только после проверки.</p>${qs.map((q,j)=>{let chosen=answers[j];return `<fieldset class="study-question"><legend><span>${j+1}.</span> ${esc(q.question)}</legend><div class="study-options">${q.options.map((opt,k)=>`<button type="button" class="study-option ${chosen===opt?'selected':''} ${checked?(opt===q.answer?'correct':chosen===opt?'wrong':''):''}" data-act="lesson-answer" data-id="${id}" data-index="${j}" data-answer="${esc(opt)}" ${checked?'disabled':''}>${esc(opt)}</button>`).join('')}</div>${checked?`<p class="study-explanation">${esc(q.explain)}</p>`:''}</fieldset>`}).join('')}<div class="study-answer-count">Выбрано: ${answersCount} из ${qs.length}</div></div><div class="card study-material"><div class="section-head"><h2>3 · Используй английский сама</h2><span class="pill">10–20 минут</span></div><p><strong>${esc(L.prompt(wi,s.kind))}</strong></p><p class="small">Напиши минимум ${s.minWords} слов на английском. Эта часть сохраняется как выполненная самостоятельная работа, но корректность текста требует проверки преподавателем.</p><textarea class="study-writing" id="session-writing" rows="6" placeholder="Напиши свой ответ здесь...">${esc(draft)}</textarea><p class="small" id="session-word-count">${wordsCount(draft)} из ${s.minWords} слов · черновик сохраняется в этом браузере</p><div class="row wrap"><button data-act="lesson-submit" data-id="${id}" class="btn btn-primary">${svg('checkCircle')} Проверить и сохранить занятие</button>${checked?`<button data-act="lesson-retry" data-id="${id}" class="btn btn-outline">Повторить упражнения</button>`:''}</div><div class="study-result" id="lesson-feedback">${checked?feedbackMarkup(lessonFeedback,stored):stored.passed?`<div class="notice success">Занятие уже зачтено. Результат: ${stored.best}% · попыток: ${stored.attempts||1}. Ты можешь повторить его для закрепления.</div>`:''}</div></div><div class="row wrap" style="margin-top:18px"><a class="btn btn-outline" href="#/неделя?id=${wid}">К плану недели</a>${si<2?`<a class="btn btn-soft" href="#/урок?week=${wid}&session=${si+1}">Следующее занятие ${svg('arrow')}</a>`:''}</div>`}
function feedbackMarkup(result,stored){let ok=result.score>=70&&result.written;return `<div class="notice ${ok?'success':'warning'}"><strong>Результат: ${result.score}% (${result.correct} из ${result.total})</strong><p style="margin:5px 0 0">${ok?'Занятие зачтено. Письменный ответ сохранён без оценки качества.':'Для зачёта нужно не менее 70% и письменный ответ нужного объёма. Исправь ошибки и попробуй ещё раз.'}</p>${ok?`<p class="small" style="margin:5px 0 0">На этой неделе учтено ${result.days}/3 разных дней практики.</p>`:''}</div>`}
function mistakeDeck(){
  const remaining=new Map();
  for(const event of state.events||[]){
    if(event.type==='lesson' && typeof event.week==='string' && Number.isInteger(event.session)){
      const wi=P.weeks.findIndex(w=>w.id===event.week),si=event.session;if(wi<0||si<0||si>2)continue;
      const qs=L.questions(wi,L.sessions[si].kind),items=Array.isArray(event.items)?event.items:[];
      for(let i=0;i<qs.length;i++){
        const q=qs[i],answer=items.find(x=>x.id===q.id);if(!answer)continue;
        const key=event.week+'-s'+si+'-'+q.id;
        if(answer.correct)remaining.delete(key);
        else remaining.set(key,{...q,key,week:wi,session:si,weekTitle:P.weeks[wi].title,kind:q.id.startsWith('g')?'Грамматика':q.id.startsWith('v')?'Словарь':q.id.startsWith('r')?'Чтение':'Аудирование'});
      }
    }
    if(event.type==='practice'&&event.source==='errors')for(const item of event.items||[]){
      if(item.correct)remaining.delete(item.id);
    }
  }
  return [...remaining.values()].reverse();
}
function mistakesPage(){
  const deck=mistakeDeck().slice(0,12),all=mistakeDeck().length;
  return `<a class="back-link" href="#/повторение">${svg('left','class="inline-icon"')} Все варианты повторения</a>`+
    heading('Персональная практика','Мои ошибки','Упражнения формируются из вопросов, где ты ошибалась. Верный ответ убирает вопрос из очереди.',`<span class="pill">${all} на повторение</span>`)+
    (!all?`<div class="card">${mistakeFeedback?`<div class="notice success" style="margin-bottom:18px">Верно ${mistakeFeedback.correct} из ${mistakeFeedback.total}. Ошибки, которые ты исправила, убраны из списка.</div>`:''}<h2>Сейчас нет открытых ошибок</h2><p>Когда в заданиях встретится ошибка, она появится здесь. Пока можно повторить словарь и неправильные глаголы.</p><a class="btn btn-primary" href="#/словарь">Повторить слова</a></div>`:
     `<div class="card study-material"><div class="section-head"><h2>Повторить сейчас</h2><span class="pill">${deck.length} вопросов</span></div><p class="small">Сначала ответь на вопросы. После проверки будут показаны объяснения. Повторение не заменяет три обязательных занятия.</p>`+
     deck.map((q,i)=>`<fieldset class="study-question"><legend><span>${i+1}.</span> ${esc(q.question)}</legend><p class="small">Неделя ${q.week+1} · ${esc(q.kind)} · ${esc(q.weekTitle)}</p><div class="study-options">${q.options.map(option=>`<button type="button" class="study-option ${mistakeAnswers[q.key]===option?'selected':''} ${mistakeFeedback?(option===q.answer?'correct':mistakeAnswers[q.key]===option?'wrong':''):''}" data-act="mistake-answer" data-id="${esc(q.key)}" data-answer="${esc(option)}" ${mistakeFeedback?'disabled':''}>${esc(option)}</button>`).join('')}</div>${mistakeFeedback?`<p class="study-explanation">${esc(q.explain)}</p>`:''}</fieldset>`).join('')+
     `<div class="row wrap" style="margin-top:18px"><button class="btn btn-primary" data-act="mistake-submit" ${mistakeFeedback?'disabled':''}>${svg('checkCircle')} Проверить повторение</button><button class="btn btn-outline" data-act="mistake-restart">Обновить задания</button></div>${mistakeFeedback?`<div class="notice ${mistakeFeedback.score>=70?'success':'warning'}" style="margin-top:18px">Верно ${mistakeFeedback.correct} из ${mistakeFeedback.total}. ${mistakeFeedback.score>=70?'Ты справляешься — продолжай!':'Разбери объяснения и попробуй ещё раз.'}</div>`:''}</div>`);
}
function reviewPage(){let list=P.weeks.flatMap((w,wi)=>L.sessions.map((s,si)=>({w,wi,si,s,id:sessionId(w.id,si)}))),done=list.filter(a=>state.sessions?.[a.id]?.passed),hard=list.filter(a=>state.sessions?.[a.id]&&state.sessions[a.id].best<80);return `${heading('Дополнительная практика','Повторение без ограничений','Можно заниматься в любой день сверх трёх обязательных занятий. Результаты прошлых попыток сохраняются.') }<div class="grid g-3"><a class="card study-link" href="#/ошибки"><strong>${svg('target')} Мои ошибки</strong><p>Личный набор вопросов из неверных ответов (${mistakeDeck().length})</p></a><a class="card study-link" href="#/грамматика"><strong>${svg('layers')} Повторить грамматику</strong><p>Правила и мини-тесты по темам</p></a><a class="card study-link" href="#/словарь"><strong>${svg('book')} Повторить словарь</strong><p>Карточки и перевод слов</p></a><a class="card study-link" href="#/глаголы"><strong>${svg('refresh')} Неправильные глаголы</strong><p>Тренировка V2 и V3</p></a><a class="card study-link" href="#/задания"><strong>${svg('target')} Задания ОГЭ</strong><p>Короткие экзаменационные тренировки</p></a><a class="card study-link" href="#/письмо"><strong>${svg('edit')} Письмо</strong><p>Тренировка ответов на вопросы друга</p></a><a class="card study-link" href="#/говорение"><strong>${svg('mic')} Говорение</strong><p>Запись монолога</p></a></div><div class="card" style="margin-top:20px"><div class="section-head"><h2>Мои занятия для повторения</h2><span class="pill">${done.length} пройдено</span></div>${!done.length?`<p>Сначала пройди хотя бы одно занятие по плану. Оно появится здесь для повторения.</p><a href="#/занятия" class="btn btn-primary">К занятиям</a>`:`${done.slice().reverse().map(a=>`<a class="lesson-link" href="#/урок?week=${a.w.id}&session=${a.si}"><div><strong>Неделя ${a.wi+1} · ${esc(a.s.name)}</strong><p>${esc(a.w.title)} · лучший результат ${state.sessions[a.id].best}% ${state.sessions[a.id].best<80?'· стоит повторить':''}</p></div>${svg('arrow')}</a>`).join('')}`}</div>`}
function contentFor(r){if(r==='занятия')return lessonsPage();if(r==='урок')return lessonPage();if(r==='повторение')return reviewPage();if(r==='ошибки')return mistakesPage();if(r==='план')return plan();if(r==='неделя')return weekPage();if(r==='диагностика')return state.diagnostic.finishedAt?resultsPage():diagnosticIntro();if(r==='тест')return takeTest();if(r==='грамматика')return grammarPage();if(r==='правило')return rulePage();if(r==='словарь')return vocabPage();if(r==='карточки')return flashPage();if(r==='глаголы')return verbsPage();if(r==='тренажёр')return examPage();if(r==='задания')return param('id')?practiceDetail():practicePage();if(r==='письмо')return writingPage();if(r==='говорение')return speakingPage();if(r==='отчёты')return reportsPage();if(r==='материалы')return resourcesPage();if(r==='настройки')return settingsPage();return dashboard()}
function render(focus=null){let r=route();document.title=`${({главная:'Главная',занятия:'Мои занятия',урок:'Самостоятельное занятие',повторение:'Повторение',ошибки:'Мои ошибки',план:'План подготовки',диагностика:'Диагностика',тест:'Стартовый тест',грамматика:'Грамматика',словарь:'Словарь',глаголы:'Неправильные глаголы',тренажёр:'Тренажёр ОГЭ',отчёты:'Отчёты',материалы:'Материалы'})[r]||'Мой ОГЭ'} · Кристина · ОГЭ-2027`;let pos=null;if(focus){let active=document.activeElement;pos=active&&active.selectionStart!==undefined?active.selectionStart:null}$('#app').innerHTML=chrome(r,contentFor(r));if(r==='глаголы')$('#verb-card').innerHTML=verbCard();if(focus){const el=document.querySelector(`[data-filter="${focus}"]`);if(el){el.focus();if(pos!==null)el.setSelectionRange(pos,pos)}}}
function speak(text){if(!('speechSynthesis' in window)){notify('На этом устройстве недоступен синтез речи');return}try{speechSynthesis.cancel();let utter=new SpeechSynthesisUtterance(text);utter.lang='en-GB';utter.rate=.86;speechSynthesis.speak(utter)}catch(e){notify('Не удалось воспроизвести произношение')}}
function finishTest(){
  const missing=D.questions.filter(q=>!(q.id in state.diagnostic.answers));
  if(missing.length&&!confirm(`Не отвечено на ${missing.length} вопросов. Завершить тест с пропущенными ответами?`))return;
  state.diagnostic.result=computeResults();
  state.diagnostic.finishedAt=new Date().toISOString();
  track('diagnostic',{score:percent(state.diagnostic.result.correct,state.diagnostic.result.total),items:D.questions.map(q=>questionLog(q,state.diagnostic.answers[q.id],q.area==='Лексика'?'Словарь':q.area,q.area==='Грамматика'?q.level+' · стартовая диагностика':q.area+' · '+q.level))});
  const saved=save();
  // Скачивание — страховка от потери локального хранилища. Это не облачная копия.
  try{download('Кристина-ОГЭ-2027-диагностика.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'application/json')}catch(e){notify('Не удалось скачать копию. Скачай её в настройках.')}
  filters.reviewOpen=false;
  navlink('диагностика');
  notify(saved?'Результат сохранён на этом устройстве. Проверь скачанную резервную копию.':'Результат показан, но браузер НЕ сохранил его. Проверь скачанный файл.');
}
function validateVerb(value,variants){return variants.split('/').map(x=>x.trim().toLowerCase()).includes(value.trim().toLowerCase())}
function action(act,el){let id=el.dataset.id;switch(act){case'go-week':navlink('неделя?id='+id);break;case'lesson-answer':{let n=Number(el.dataset.index);lessonAnswers[id]||={};lessonAnswers[id][n]=el.dataset.answer;const group=el.closest('.study-question');if(group){group.querySelectorAll('.study-option').forEach(button=>button.classList.toggle('selected',button===el))}const counter=$('.study-answer-count'),total=L.questions(P.weeks.findIndex(w=>w.id===(param('week')||P.weeks[weekNow()].id)),L.sessions[Number(param('session'))].kind).length;if(counter)counter.textContent=`Выбрано: ${Object.keys(lessonAnswers[id]).length} из ${total}`;break}case'listen-session':{let wi=Number(el.dataset.week),audio=L.listen(wi);if(audio)speak(audio.text);break}case'show-transcript':{let t=$('#lesson-transcript');if(t)t.classList.toggle('hidden');break}case'lesson-submit':{let [week,siRaw]=id.split('-s'),si=Number(siRaw),wi=P.weeks.findIndex(w=>w.id===week);if(wi<0||si<0||si>2)return;let item=L.sessions[si],q=L.questions(wi,item.kind),ans=lessonAnswers[id]||{},count=Object.keys(ans).length,text=$('#session-writing')?.value||state.sessionDrafts?.[id]||'';state.sessionDrafts[id]=text;if(count<q.length){save();notify(`Ответь на все ${q.length} вопросов (сейчас ${count})`);return}let score=percent(q.filter((question,i)=>ans[i]===question.answer).length,q.length),written=wordsCount(text)>=item.minWords,passed=score>=70&&written,prior=state.sessions[id]||{},now=new Date().toISOString(),date=localISO();state.sessions[id]={best:Math.max(score,prior.best||0),passed:!!prior.passed||passed,attempts:(prior.attempts||0)+1,firstPassedAt:prior.firstPassedAt||(passed?now:null),lastAttemptAt:now,lastScore:score};if(passed){let days=state.weekStudyDays[week]||[];if(!days.includes(date))days.push(date);state.weekStudyDays[week]=days.sort();/* Учёт каждой попытки, включая незачтённые, находится ниже */}track('lesson',{week,session:si,score,passed,topic:item.kind==='grammar'?P.weeks[wi].grammar:item.kind==='reading'?L.vocabTopic(wi).title:P.weeks[wi].skill,items:q.map((question,i)=>questionLog(question,ans[i],question.id.startsWith('g')?'Грамматика':question.id.startsWith('v')?'Словарь':question.id.startsWith('r')?'Чтение':'Аудирование',question.id.startsWith('g')?P.weeks[wi].grammar:question.id.startsWith('r')?L.reading(wi).topic:question.id.startsWith('v')?L.vocabTopic(wi).title:P.weeks[wi].skill))});save();lessonFeedback={id,done:true,score,correct:q.filter((question,i)=>ans[i]===question.answer).length,total:q.length,written,days:weekDayCount(week)};render();notify(passed?'Занятие зачтено!':'Пока не зачтено. Посмотри ошибки и повтори.');break}case'mistake-answer':{mistakeAnswers[id]=el.dataset.answer;const group=el.closest('.study-question');if(group)group.querySelectorAll('.study-option').forEach(b=>b.classList.toggle('selected',b===el));break}case'mistake-submit':{const deck=mistakeDeck().slice(0,12);if(deck.some(q=>!(q.key in mistakeAnswers))){notify('Ответь на все вопросы повторения');return}const items=deck.map(q=>({id:q.key,domain:q.kind,topic:q.studyTopic||q.weekTitle,correct:mistakeAnswers[q.key]===q.answer}));const correct=items.filter(x=>x.correct).length;mistakeFeedback={correct,total:items.length,score:percent(correct,items.length)};track('practice',{source:'errors',topic:'Повторение ошибок',items});save();render();break}case'mistake-restart':mistakeAnswers={};mistakeFeedback=null;render();break;case'lesson-retry':{delete lessonAnswers[id];lessonFeedback=null;render();break}case'start-test':filters.diagnosticIndex=0;if(state.diagnostic.finishedAt){if(!confirm('Пройти диагностику заново? Предыдущий результат будет заменён.'))return;state.diagnostic={answers:{},finishedAt:null,result:null};save()}else{let empty=D.questions.findIndex(q=>!(q.id in state.diagnostic.answers));filters.diagnosticIndex=Math.max(0,empty)}navlink('тест');break;case'answer-test':state.diagnostic.answers[id]=el.dataset.option;save();render();break;case'test-next':filters.diagnosticIndex=Math.min(D.questions.length-1,filters.diagnosticIndex+1);render();break;case'test-prev':filters.diagnosticIndex=Math.max(0,filters.diagnosticIndex-1);render();break;case'test-first-empty':{let x=D.questions.findIndex(q=>!(q.id in state.diagnostic.answers));if(x<0)notify('Все вопросы заполнены');else{filters.diagnosticIndex=x;render()}break}case'finish-test':finishTest();break;case'show-results':navlink('диагностика');break;case'reset-test':if(confirm('Начать заново? Последние ответы будут заменены.')){state.diagnostic={answers:{},finishedAt:null,result:null};save();filters.diagnosticIndex=0;navlink('диагностика')}break;case'toggle-review':filters.reviewOpen=!filters.reviewOpen;render();break;case'toggle-grammar':{let old=state.grammar[id]||{};state.grammar[id]={...old,done:!old.done};save();render();break}case'check-rule':{let topic=P.grammarGroups.flatMap(g=>g.topics).find(t=>t.id===id),rule=topic&&P.rules[topic.title];if(!rule)return;let sels=[...document.querySelectorAll('[data-rule-choice]')];if(sels.some(s=>!s.value)){notify('Выбери ответы на оба вопроса');return}let score=percent(rule.check.filter((q,i)=>sels[i].value===q[1]).length,rule.check.length),old=state.grammar[id]||{};state.grammar[id]={done:score===100||!!old.done,best:Math.max(score,old.best||0)};track('grammar',{topic:topic.title,score,passed:score===100,items:rule.check.map((q,i)=>({id:id+'-'+i,domain:'Грамматика',topic:topic.title,correct:sels[i].value===q[1]}))});save();let out=$('#rule-feedback');out.className='notice '+(score===100?'success':'warning');out.textContent=`${score}% верно. ${score===100?'Отлично! Тема отмечена как изученная.':'Повтори правило и попробуй ещё раз.'}`;break}case'vocab-topic':filters.vocabTopic=id;filters.vocabSearch='';filters.vocabStatus='all';filters.flashIndex=0;render();break;case'word-status':{let s=el.dataset.status;const previous=state.vocab[id];state.vocab[id]=previous===s?'new':s;if(state.vocab[id]==='known'&&previous!=='known'){const word=P.vocabulary.flatMap(t=>t.words.map(w=>({word:w,topic:t.title}))).find(x=>x.word.id===id);track('vocab',{word:id,topic:word?.topic||'Словарь',status:'known'})}save();render();break}case'speak':speak(el.dataset.speak);break;case'flash-flip':filters.flashShow=true;render();break;case'flash-prev':filters.flashIndex=Math.max(0,filters.flashIndex-1);filters.flashShow=false;render();break;case'flash-status':{let tid=param('topic')||'v1',t=P.vocabulary.find(x=>x.id===tid)||P.vocabulary[0],word=t.words[filters.flashIndex];const previous=state.vocab[word.id];state.vocab[word.id]=el.dataset.status;if(state.vocab[word.id]==='known'&&previous!=='known')track('vocab',{word:word.id,topic:t.title,status:'known'});save();if(filters.flashIndex<t.words.length-1)filters.flashIndex++;filters.flashShow=false;render();break}case'toggle-verb':state.verbs[id]=!state.verbs[id];save();render();break;case'next-verb':currentVerbIndex=Math.floor(Math.random()*P.verbs.length);$('#verb-card').innerHTML=verbCard();break;case'check-verb':{let v=P.verbs[currentVerbIndex],entered=($('#verb-answer')?.value||'').trim();if(!entered){notify('Впиши форму глагола');return}let correct=validateVerb(entered,v[filters.verbStage]);let box=$('#verb-feedback');box.className='notice '+(correct?'success':'warning');box.textContent=correct?'Правильно!':'Правильная форма: '+v[filters.verbStage];track('verb',{topic:v.v1,score:correct?100:0,items:[{id:v.id+'-'+filters.verbStage,domain:'Неправильные глаголы',topic:v.v1,correct}]});if(correct)state.verbs[v.id]=true;save();break}case'practice-answer':{let x=Number(el.dataset.index);practiceAnswers[id]||={};practiceAnswers[id][x]=el.dataset.answer;render();break}case'practice-check':{let p=practices.find(x=>x.id===id);if(!p)return;let missing=p.questions.length-Object.keys(practiceAnswers[id]||{}).length;if(missing){notify('Осталось ответить на '+missing+' вопрос(ов)');return}let score=percent(p.questions.filter((q,i)=>practiceAnswers[id][i]===q[1]).length,p.questions.length);state.practice[id]=Math.max(score,state.practice[id]||0);track('practice',{topic:p.label,score,items:p.questions.map((q,i)=>({id:id+'-'+i,domain:p.id==='p2'?'Словообразование':p.id==='p4'?'Словарь':p.id==='p3'?'Чтение':'Грамматика',topic:p.label,correct:practiceAnswers[id][i]===q[1]}))});filters.practiceChecked=id;save();render();break}case'practice-retry':delete practiceAnswers[id];filters.practiceChecked=null;lessonFeedback=null;render();break;case'cloud-login':case'cloud-register':{const email=$('#cloud-email')?.value?.trim(),pw=$('#cloud-password')?.value;window.OGE_CLOUD?.signIn(email,pw,act==='cloud-register').then(msg=>notify(msg)).catch(e=>notify('Ошибка: '+e.message));break}case'cloud-invite':{window.OGE_CLOUD?.createViewerCode().then(()=>notify('Код доступа создан')).catch(e=>notify('Ошибка: '+e.message));break}case'cloud-revoke':{if(confirm('Отключить доступ к результатам всем наблюдателям?'))window.OGE_CLOUD?.revokeViewers().then(()=>notify('Доступ наблюдателей отключён')).catch(e=>notify('Ошибка: '+e.message));break}case'cloud-sync':window.OGE_CLOUD?.sync().then(()=>{const status=window.OGE_CLOUD?.status?.();notify(status?.error|| (status?.syncedAt?'Синхронизация выполнена':'Синхронизация не подтверждена'))}).catch(e=>notify('Ошибка: '+e.message));break;case'cloud-logout':window.OGE_CLOUD?.signOut().catch(e=>notify('Ошибка: '+e.message));break;case'copy-report':{const report=reportPreview(el.dataset.period==='month'?'month':'week');if(report&&navigator.clipboard?.writeText)navigator.clipboard.writeText(report.text).then(()=>notify('Отчёт скопирован')).catch(()=>notify('Не удалось скопировать текст'));else notify('Копирование недоступно. Выдели текст отчёта вручную.');break}case'download-writing':download('Письмо-Кристины.txt',state.writing.text,'text/plain;charset=utf-8');break;case'export-data':download('Кристина-ОГЭ-2027-прогресс.json',JSON.stringify({...state,exportedAt:new Date().toISOString()},null,2),'application/json');notify('Резервная копия создана');break;case'reset-all':if(confirm('Сбросить ВСЕ результаты, слова и черновики на этом устройстве? Это действие нельзя отменить без резервной копии.')){state=defaults();save();filters.diagnosticIndex=0;navlink('главная');render();notify('Данные сброшены')}break;case'record-toggle':toggleRecorder();break}}
function download(name,content,type){let blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000)}
async function restore(file){if(!file)return;try{if(file.size>1000000)throw Error('Файл слишком большой');let obj=JSON.parse(await file.text());if(!obj||obj.studentId!==C.student.id||obj.version!==1||!obj.diagnostic||!obj.weeks||!obj.vocab||!obj.grammar)throw Error('Это не резервная копия кабинета Кристины');if(!confirm('Заменить текущий прогресс данными из файла?'))return;state={...defaults(),...obj,sessions:obj.sessions||{},sessionDrafts:obj.sessionDrafts||{},weekStudyDays:obj.weekStudyDays||{}};save();render();notify('Прогресс восстановлен')}catch(e){notify('Не удалось восстановить: '+e.message)}}
async function toggleRecorder(){if(recording){if(rec&&rec.state==='recording')rec.stop();recording=false;return}if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){notify('Запись недоступна в этом браузере или по этому адресу. Используй HTTPS или localhost.');return}try{recStream=await navigator.mediaDevices.getUserMedia({audio:true});recChunks=[];recMime=MediaRecorder.isTypeSupported('audio/webm')?'audio/webm':MediaRecorder.isTypeSupported('audio/mp4')?'audio/mp4':'';rec=new MediaRecorder(recStream,recMime?{mimeType:recMime}:undefined);rec.ondataavailable=e=>{if(e.data?.size)recChunks.push(e.data)};rec.onstop=()=>{recording=false;recStream?.getTracks().forEach(t=>t.stop());if(recUrl)URL.revokeObjectURL(recUrl);let blob=new Blob(recChunks,{type:rec.mimeType||'audio/webm'});recUrl=URL.createObjectURL(blob);let ext=blob.type.includes('mp4')?'m4a':'webm';let box=$('#record-audio');if(box)box.innerHTML=`<div class="task-box"><strong>Запись готова</strong><audio controls src="${recUrl}" style="width:100%;margin:13px 0"></audio><a class="btn btn-primary" href="${recUrl}" download="Кристина-монолог.${ext}">${svg('download')} Скачать аудиофайл</a></div>`;let badge=$('#record-status');if(badge)badge.textContent='Запись завершена';let btn=$('#record-button');if(btn)btn.innerHTML=`${svg('mic')} Записать ещё раз`};rec.start();recording=true;let badge=$('#record-status');if(badge){badge.textContent='Идёт запись';badge.className='pill orange'}let btn=$('#record-button');if(btn)btn.innerHTML=`${svg('pause')} Остановить запись`;}catch(e){recording=false;recStream?.getTracks().forEach(t=>t.stop());notify('Не удалось получить доступ к микрофону. Проверь разрешения.')}}
let inputTimer=null;document.addEventListener('click',e=>{const el=e.target.closest('[data-act]');if(!el)return;if(el.tagName==='A'&&!el.dataset.act)return;e.preventDefault();action(el.dataset.act,el)});
document.addEventListener('change',e=>{let el=e.target;if(el.dataset.act==='vocab-status'){filters.vocabStatus=el.value;render()}else if(el.dataset.act==='verb-stage'){filters.verbStage=el.value;$('#verb-card').innerHTML=verbCard()}else if(el.dataset.act==='writing-check'){state.writing.checks[el.dataset.index]=el.checked;save()}else if(el.id==='restore-file')restore(el.files[0])});
document.addEventListener('input',e=>{let el=e.target;if(el.dataset.filter){let key={grammar:'grammarSearch',vocab:'vocabSearch',verbs:'verbSearch'}[el.dataset.filter];if(key){filters[key]=el.value;clearTimeout(inputTimer);inputTimer=setTimeout(()=>render(el.dataset.filter),120)}}else if(el.id==='session-writing'){let wi=param('week')||P.weeks[weekNow()].id,si=Number(param('session')),lid=sessionId(wi,si);state.sessionDrafts[lid]=el.value;save();let b=$('#session-word-count');if(b)b.textContent=`${wordsCount(el.value)} из ${L.sessions[si].minWords} слов · черновик сохраняется в этом браузере`}else if(el.id==='writing-text'){state.writing.text=el.value;save();let badge=el.closest('.card').querySelector('.section-head .pill');if(badge){let n=(el.value.trim().match(/\b[\w]+(?:['’\-][\w]+)*\b/g)||[]).length;badge.textContent=n+' слов';badge.className='pill '+(n>=100&&n<=120?'green':'gray')}}});
window.addEventListener('oge-cloud-status',()=>{if(['настройки','отчёты'].includes(route()))render()});
window.addEventListener('hashchange',()=>{filters.practiceChecked=null;lessonFeedback=null;render();window.scrollTo(0,0)});
window.addEventListener('beforeunload',()=>{if(recording&&rec?.state==='recording')rec.stop();if(recUrl)URL.revokeObjectURL(recUrl)});
render();
})();
